//! A small, self-contained CSV reader/writer with byte-oriented records.

use std::fmt;
use std::io::{self, Read, Seek, SeekFrom, Write};

/// Position of a record within the input stream.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Position {
    byte: u64,
    line: u64,
    record: u64,
}

impl Position {
    pub fn new() -> Position {
        Position { byte: 0, line: 1, record: 0 }
    }
    pub fn byte(&self) -> u64 {
        self.byte
    }
    pub fn line(&self) -> u64 {
        self.line
    }
    pub fn record(&self) -> u64 {
        self.record
    }
    pub fn set_byte(&mut self, b: u64) -> &mut Position {
        self.byte = b;
        self
    }
    pub fn set_line(&mut self, l: u64) -> &mut Position {
        self.line = l;
        self
    }
    pub fn set_record(&mut self, r: u64) -> &mut Position {
        self.record = r;
        self
    }
}

/// Errors produced while reading or writing CSV data.
#[derive(Debug)]
pub enum Error {
    Io(io::Error),
    UnequalLengths {
        pos: Option<Position>,
        expected_len: u64,
        len: u64,
    },
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            Error::Io(ref err) => err.fmt(f),
            Error::UnequalLengths { pos: None, expected_len, len } => write!(
                f,
                "CSV error: found record with {} fields, but the previous record has {} fields",
                len, expected_len
            ),
            Error::UnequalLengths { pos: Some(ref pos), expected_len, len } => write!(
                f,
                "CSV error: record {} (line: {}, byte: {}): \
                 found record with {} fields, but the previous record has {} fields",
                pos.record(),
                pos.line(),
                pos.byte(),
                len,
                expected_len
            ),
        }
    }
}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Error {
        Error::Io(err)
    }
}

pub type Result<T> = std::result::Result<T, Error>;

/// A record of byte fields stored in a single flat buffer.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ByteRecord {
    data: Vec<u8>,
    ends: Vec<usize>,
    pos: Option<Position>,
}

impl ByteRecord {
    pub fn new() -> ByteRecord {
        ByteRecord { data: Vec::new(), ends: Vec::new(), pos: None }
    }
    pub fn from_fields<I, T>(fields: I) -> ByteRecord
    where
        I: IntoIterator<Item = T>,
        T: AsRef<[u8]>,
    {
        let mut r = ByteRecord::new();
        for f in fields {
            r.push_field(f.as_ref());
        }
        r
    }
    pub fn clear(&mut self) {
        self.data.clear();
        self.ends.clear();
        self.pos = None;
    }
    pub fn len(&self) -> usize {
        self.ends.len()
    }
    pub fn is_empty(&self) -> bool {
        self.ends.is_empty()
    }
    pub fn push_field(&mut self, field: &[u8]) {
        self.data.extend_from_slice(field);
        self.ends.push(self.data.len());
    }
    pub fn get(&self, i: usize) -> Option<&[u8]> {
        if i >= self.ends.len() {
            return None;
        }
        let start = if i == 0 { 0 } else { self.ends[i - 1] };
        Some(&self.data[start..self.ends[i]])
    }
    pub fn iter(&self) -> ByteRecordIter<'_> {
        ByteRecordIter { rec: self, i: 0 }
    }
    pub fn position(&self) -> Option<&Position> {
        self.pos.as_ref()
    }
    pub fn set_position(&mut self, pos: Option<Position>) {
        self.pos = pos;
    }
    pub fn truncate(&mut self, n: usize) {
        if n < self.ends.len() {
            let end = if n == 0 { 0 } else { self.ends[n - 1] };
            self.ends.truncate(n);
            self.data.truncate(end);
        }
    }
    pub fn to_vecs(&self) -> Vec<Vec<u8>> {
        self.iter().map(|f| f.to_vec()).collect()
    }
}

impl<'a> IntoIterator for &'a ByteRecord {
    type Item = &'a [u8];
    type IntoIter = ByteRecordIter<'a>;
    fn into_iter(self) -> ByteRecordIter<'a> {
        self.iter()
    }
}

pub struct ByteRecordIter<'a> {
    rec: &'a ByteRecord,
    i: usize,
}

impl<'a> Iterator for ByteRecordIter<'a> {
    type Item = &'a [u8];
    fn next(&mut self) -> Option<&'a [u8]> {
        let r = self.rec.get(self.i);
        if r.is_some() {
            self.i += 1;
        }
        r
    }
}

/// Configuration for reading CSV data.
#[derive(Clone, Debug)]
pub struct ReaderBuilder {
    delimiter: u8,
    quote: u8,
    escape: Option<u8>,
    double_quote: bool,
    quoting: bool,
    has_headers: bool,
    flexible: bool,
}

impl Default for ReaderBuilder {
    fn default() -> ReaderBuilder {
        ReaderBuilder {
            delimiter: b',',
            quote: b'"',
            escape: None,
            double_quote: true,
            quoting: true,
            has_headers: true,
            flexible: false,
        }
    }
}

impl ReaderBuilder {
    pub fn new() -> ReaderBuilder {
        ReaderBuilder::default()
    }
    pub fn delimiter(&mut self, d: u8) -> &mut ReaderBuilder {
        self.delimiter = d;
        self
    }
    pub fn quote(&mut self, q: u8) -> &mut ReaderBuilder {
        self.quote = q;
        self
    }
    pub fn escape(&mut self, e: Option<u8>) -> &mut ReaderBuilder {
        self.escape = e;
        self
    }
    pub fn double_quote(&mut self, yes: bool) -> &mut ReaderBuilder {
        self.double_quote = yes;
        self
    }
    pub fn quoting(&mut self, yes: bool) -> &mut ReaderBuilder {
        self.quoting = yes;
        self
    }
    pub fn has_headers(&mut self, yes: bool) -> &mut ReaderBuilder {
        self.has_headers = yes;
        self
    }
    pub fn flexible(&mut self, yes: bool) -> &mut ReaderBuilder {
        self.flexible = yes;
        self
    }
    pub fn from_reader<R: Read>(&self, rdr: R) -> Reader<R> {
        Reader::new(self.clone(), rdr)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum State {
    StartRecord,
    StartField,
    InField,
    InQuotedField,
    InEscapedQuote,
    InDoubleEscapedQuote,
}

const BUF_SIZE: usize = 64 * 1024;

/// A CSV reader over any `io::Read`.
pub struct Reader<R> {
    cfg: ReaderBuilder,
    inner: R,
    buf: Vec<u8>,
    buf_pos: usize,
    buf_cap: usize,
    cur_pos: Position,
    state: State,
    eof: bool,
    headers: Option<ByteRecord>,
    first_field_count: Option<u64>,
    first: bool,
    seeked: bool,
    bom_checked: bool,
    stream_eof: bool,
}

impl<R: Read> Reader<R> {
    fn new(cfg: ReaderBuilder, rdr: R) -> Reader<R> {
        Reader {
            cfg,
            inner: rdr,
            buf: vec![0; BUF_SIZE],
            buf_pos: 0,
            buf_cap: 0,
            cur_pos: Position::new(),
            state: State::StartRecord,
            eof: false,
            headers: None,
            first_field_count: None,
            first: false,
            seeked: false,
            bom_checked: false,
            stream_eof: false,
        }
    }

    pub fn has_headers(&self) -> bool {
        self.cfg.has_headers
    }

    pub fn position(&self) -> &Position {
        &self.cur_pos
    }

    pub fn is_done(&self) -> bool {
        self.eof
    }

    /// Returns the header record (reading it if needed). With `has_headers`
    /// disabled the first record is still returned here, but it will also be
    /// yielded by `read_byte_record`.
    pub fn byte_headers(&mut self) -> Result<&ByteRecord> {
        if self.headers.is_none() {
            let mut rec = ByteRecord::new();
            self.read_byte_record_impl(&mut rec)?;
            self.set_headers_impl(rec);
        }
        Ok(self.headers.as_ref().unwrap())
    }

    fn set_headers_impl(&mut self, rec: ByteRecord) {
        self.headers = Some(rec);
    }

    pub fn read_byte_record(&mut self, record: &mut ByteRecord) -> Result<bool> {
        if !self.seeked && !self.cfg.has_headers && !self.first {
            if let Some(ref headers) = self.headers {
                self.first = true;
                record.clone_from(headers);
                return Ok(!record.is_empty());
            }
        }
        let ok = self.read_byte_record_impl(record)?;
        self.first = true;
        if !self.seeked && self.headers.is_none() {
            self.set_headers_impl(record.clone());
            if self.cfg.has_headers {
                return self.read_byte_record_impl(record);
            }
        }
        Ok(ok)
    }

    /// An iterator over the remaining records.
    pub fn byte_records(&mut self) -> ByteRecordsIter<'_, R> {
        ByteRecordsIter { rdr: self, rec: ByteRecord::new() }
    }

    pub fn into_byte_records(self) -> ByteRecordsIntoIter<R> {
        ByteRecordsIntoIter { rdr: self, rec: ByteRecord::new() }
    }

    fn fill_buf(&mut self) -> io::Result<bool> {
        if self.buf_pos < self.buf_cap {
            return Ok(true);
        }
        if self.stream_eof {
            return Ok(false);
        }
        loop {
            match self.inner.read(&mut self.buf) {
                Ok(0) => {
                    self.stream_eof = true;
                    self.buf_pos = 0;
                    self.buf_cap = 0;
                    return Ok(false);
                }
                Ok(n) => {
                    self.buf_pos = 0;
                    self.buf_cap = n;
                    return Ok(true);
                }
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(e),
            }
        }
    }

    fn strip_bom(&mut self) -> io::Result<()> {
        self.bom_checked = true;
        // Need up to 3 bytes available.
        if !self.fill_buf()? {
            return Ok(());
        }
        // Make sure we have 3 bytes buffered if possible.
        while self.buf_cap - self.buf_pos < 3 && !self.stream_eof {
            // compact and read more
            let avail = self.buf_cap - self.buf_pos;
            let tmp: Vec<u8> = self.buf[self.buf_pos..self.buf_cap].to_vec();
            self.buf[..avail].copy_from_slice(&tmp);
            self.buf_pos = 0;
            self.buf_cap = avail;
            match self.inner.read(&mut self.buf[avail..]) {
                Ok(0) => {
                    self.stream_eof = true;
                    break;
                }
                Ok(n) => self.buf_cap += n,
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(e),
            }
        }
        if self.buf_cap - self.buf_pos >= 3
            && &self.buf[self.buf_pos..self.buf_pos + 3] == b"\xef\xbb\xbf"
        {
            self.buf_pos += 3;
            self.cur_pos.byte += 3;
        }
        Ok(())
    }

    fn read_byte_record_impl(&mut self, record: &mut ByteRecord) -> Result<bool> {
        record.clear();
        record.set_position(Some(self.cur_pos.clone()));
        if self.eof {
            return Ok(false);
        }
        if !self.bom_checked {
            self.strip_bom()?;
        }
        let delim = self.cfg.delimiter;
        let quote = self.cfg.quote;
        let escape = self.cfg.escape;
        let double_quote = self.cfg.double_quote;
        let quoting = self.cfg.quoting;
        let mut state = self.state;
        let mut data = std::mem::take(&mut record.data);
        let mut ends = std::mem::take(&mut record.ends);
        let mut nbytes: u64 = 0;
        let mut nlines: u64 = 0;
        let mut got_record = false;
        'outer: loop {
            if !self.fill_buf()? {
                // EOF handling
                match state {
                    State::StartRecord => {
                        self.eof = true;
                    }
                    _ => {
                        ends.push(data.len());
                        got_record = true;
                        self.eof = true;
                    }
                }
                state = State::StartRecord;
                break;
            }
            let buf = &self.buf[self.buf_pos..self.buf_cap];
            let mut i = 0;
            while i < buf.len() {
                let b = buf[i];
                match state {
                    State::StartRecord => {
                        if b == b'\n' || b == b'\r' {
                            if b == b'\n' {
                                nlines += 1;
                            }
                            i += 1;
                        } else {
                            state = State::StartField;
                        }
                    }
                    State::StartField => {
                        if quoting && b == quote {
                            state = State::InQuotedField;
                            i += 1;
                        } else if b == delim {
                            ends.push(data.len());
                            i += 1;
                        } else if b == b'\n' || b == b'\r' {
                            ends.push(data.len());
                            if b == b'\n' {
                                nlines += 1;
                            }
                            i += 1;
                            got_record = true;
                            state = State::StartRecord;
                            self.buf_pos += i;
                            nbytes += i as u64;
                            break 'outer;
                        } else {
                            data.push(b);
                            state = State::InField;
                            i += 1;
                        }
                    }
                    State::InField => {
                        if b == delim {
                            ends.push(data.len());
                            state = State::StartField;
                            i += 1;
                        } else if b == b'\n' || b == b'\r' {
                            ends.push(data.len());
                            if b == b'\n' {
                                nlines += 1;
                            }
                            i += 1;
                            got_record = true;
                            state = State::StartRecord;
                            self.buf_pos += i;
                            nbytes += i as u64;
                            break 'outer;
                        } else {
                            data.push(b);
                            i += 1;
                        }
                    }
                    State::InQuotedField => {
                        if b == quote {
                            state = State::InDoubleEscapedQuote;
                        } else if escape == Some(b) {
                            state = State::InEscapedQuote;
                        } else {
                            if b == b'\n' {
                                nlines += 1;
                            }
                            data.push(b);
                        }
                        i += 1;
                    }
                    State::InEscapedQuote => {
                        if b == b'\n' {
                            nlines += 1;
                        }
                        data.push(b);
                        state = State::InQuotedField;
                        i += 1;
                    }
                    State::InDoubleEscapedQuote => {
                        if double_quote && b == quote {
                            data.push(b);
                            state = State::InQuotedField;
                            i += 1;
                        } else if b == delim {
                            ends.push(data.len());
                            state = State::StartField;
                            i += 1;
                        } else if b == b'\n' || b == b'\r' {
                            ends.push(data.len());
                            if b == b'\n' {
                                nlines += 1;
                            }
                            i += 1;
                            got_record = true;
                            state = State::StartRecord;
                            self.buf_pos += i;
                            nbytes += i as u64;
                            break 'outer;
                        } else {
                            data.push(b);
                            state = State::InField;
                            i += 1;
                        }
                    }
                }
            }
            self.buf_pos += i;
            nbytes += i as u64;
        }
        self.state = state;
        self.cur_pos.byte += nbytes;
        self.cur_pos.line += nlines;
        record.data = data;
        record.ends = ends;
        if got_record {
            self.add_record(record)?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn add_record(&mut self, record: &ByteRecord) -> Result<()> {
        let i = self.cur_pos.record;
        self.cur_pos.record = i + 1;
        if !self.cfg.flexible {
            match self.first_field_count {
                None => self.first_field_count = Some(record.len() as u64),
                Some(expected) => {
                    if record.len() as u64 != expected {
                        return Err(Error::UnequalLengths {
                            pos: record.position().cloned(),
                            expected_len: expected,
                            len: record.len() as u64,
                        });
                    }
                }
            }
        }
        Ok(())
    }
}

impl<R: Read + Seek> Reader<R> {
    /// Seeks the underlying reader to the given position and resets parser
    /// state. Headers are read first if they have not been yet.
    pub fn seek(&mut self, pos: Position) -> Result<()> {
        self.byte_headers()?;
        self.seeked = true;
        if pos.byte() == self.cur_pos.byte() {
            return Ok(());
        }
        self.inner.seek(SeekFrom::Start(pos.byte()))?;
        self.buf_pos = 0;
        self.buf_cap = 0;
        self.stream_eof = false;
        self.state = State::StartRecord;
        self.cur_pos = pos;
        self.eof = false;
        self.bom_checked = self.cur_pos.byte() != 0;
        Ok(())
    }
}

pub struct ByteRecordsIter<'r, R: 'r> {
    rdr: &'r mut Reader<R>,
    rec: ByteRecord,
}

impl<'r, R: Read> Iterator for ByteRecordsIter<'r, R> {
    type Item = Result<ByteRecord>;
    fn next(&mut self) -> Option<Result<ByteRecord>> {
        match self.rdr.read_byte_record(&mut self.rec) {
            Err(err) => Some(Err(err)),
            Ok(true) => Some(Ok(self.rec.clone())),
            Ok(false) => None,
        }
    }
}

pub struct ByteRecordsIntoIter<R> {
    rdr: Reader<R>,
    rec: ByteRecord,
}

impl<R: Read> Iterator for ByteRecordsIntoIter<R> {
    type Item = Result<ByteRecord>;
    fn next(&mut self) -> Option<Result<ByteRecord>> {
        match self.rdr.read_byte_record(&mut self.rec) {
            Err(err) => Some(Err(err)),
            Ok(true) => Some(Ok(self.rec.clone())),
            Ok(false) => None,
        }
    }
}

/// Record terminator used when writing.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Terminator {
    CRLF,
    Any(u8),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum QuoteStyle {
    Necessary,
    Always,
}

#[derive(Clone, Debug)]
pub struct WriterBuilder {
    delimiter: u8,
    terminator: Terminator,
    quote: u8,
    quote_style: QuoteStyle,
    escape: u8,
    double_quote: bool,
    flexible: bool,
    crlf: bool,
}

impl Default for WriterBuilder {
    fn default() -> WriterBuilder {
        WriterBuilder {
            delimiter: b',',
            terminator: Terminator::Any(b'\n'),
            quote: b'"',
            quote_style: QuoteStyle::Necessary,
            escape: b'\\',
            double_quote: true,
            flexible: false,
            crlf: false,
        }
    }
}

impl WriterBuilder {
    pub fn new() -> WriterBuilder {
        WriterBuilder::default()
    }
    pub fn delimiter(&mut self, d: u8) -> &mut WriterBuilder {
        self.delimiter = d;
        self
    }
    pub fn terminator(&mut self, t: Terminator) -> &mut WriterBuilder {
        self.terminator = t;
        self
    }
    pub fn quote(&mut self, q: u8) -> &mut WriterBuilder {
        self.quote = q;
        self
    }
    pub fn quote_style(&mut self, s: QuoteStyle) -> &mut WriterBuilder {
        self.quote_style = s;
        self
    }
    pub fn escape(&mut self, e: u8) -> &mut WriterBuilder {
        self.escape = e;
        self
    }
    pub fn double_quote(&mut self, yes: bool) -> &mut WriterBuilder {
        self.double_quote = yes;
        self
    }
    pub fn flexible(&mut self, yes: bool) -> &mut WriterBuilder {
        self.flexible = yes;
        self
    }
    pub fn from_writer<W: Write>(&self, wtr: W) -> Writer<W> {
        let mut requires_quotes = [false; 256];
        requires_quotes[self.delimiter as usize] = true;
        requires_quotes[self.quote as usize] = true;
        if !self.double_quote {
            requires_quotes[self.escape as usize] = true;
        }
        requires_quotes[b'\r' as usize] = true;
        requires_quotes[b'\n' as usize] = true;
        if let Terminator::Any(b) = self.terminator {
            requires_quotes[b as usize] = true;
        }
        Writer {
            cfg: self.clone(),
            requires_quotes,
            inner: Some(wtr),
            buf: Vec::with_capacity(BUF_SIZE),
            fields_written: 0,
            record_bytes: 0,
            first_field_count: None,
            panicked: false,
        }
    }
}

/// A CSV writer that buffers output and flushes on drop.
pub struct Writer<W: Write> {
    cfg: WriterBuilder,
    requires_quotes: [bool; 256],
    inner: Option<W>,
    buf: Vec<u8>,
    fields_written: u64,
    record_bytes: usize,
    first_field_count: Option<u64>,
    panicked: bool,
}

impl<W: Write> Drop for Writer<W> {
    fn drop(&mut self) {
        if self.inner.is_some() && !self.panicked {
            let _ = self.flush();
        }
    }
}

impl<W: Write> Writer<W> {
    fn needs_quotes(&self, field: &[u8]) -> bool {
        field.iter().any(|&b| self.requires_quotes[b as usize])
    }

    pub fn write_field(&mut self, field: &[u8]) -> Result<()> {
        if self.fields_written > 0 {
            self.buf.push(self.cfg.delimiter);
            self.record_bytes += 1;
        }
        let quote = match self.cfg.quote_style {
            QuoteStyle::Always => true,
            QuoteStyle::Necessary => self.needs_quotes(field),
        };
        if quote {
            let q = self.cfg.quote;
            self.buf.push(q);
            for &b in field {
                if b == q {
                    if self.cfg.double_quote {
                        self.buf.push(q);
                        self.buf.push(q);
                    } else {
                        self.buf.push(self.cfg.escape);
                        self.buf.push(q);
                    }
                } else {
                    self.buf.push(b);
                }
            }
            self.buf.push(q);
            self.record_bytes += field.len() + 2;
        } else {
            self.buf.extend_from_slice(field);
            self.record_bytes += field.len();
        }
        self.fields_written += 1;
        self.maybe_flush_buf()?;
        Ok(())
    }

    fn check_field_count(&mut self) -> Result<()> {
        if !self.cfg.flexible {
            match self.first_field_count {
                None => self.first_field_count = Some(self.fields_written),
                Some(expected) if expected != self.fields_written => {
                    return Err(Error::UnequalLengths {
                        pos: None,
                        expected_len: expected,
                        len: self.fields_written,
                    });
                }
                Some(_) => {}
            }
        }
        Ok(())
    }

    pub fn write_terminator(&mut self) -> Result<()> {
        self.check_field_count()?;
        if self.record_bytes == 0 {
            let q = self.cfg.quote;
            self.buf.push(q);
            self.buf.push(q);
        }
        match self.cfg.terminator {
            Terminator::CRLF => self.buf.extend_from_slice(b"\r\n"),
            Terminator::Any(b) => self.buf.push(b),
        }
        self.fields_written = 0;
        self.record_bytes = 0;
        self.maybe_flush_buf()?;
        Ok(())
    }

    pub fn write_record<I, T>(&mut self, record: I) -> Result<()>
    where
        I: IntoIterator<Item = T>,
        T: AsRef<[u8]>,
    {
        for f in record {
            self.write_field(f.as_ref())?;
        }
        self.write_terminator()
    }

    pub fn write_byte_record(&mut self, record: &ByteRecord) -> Result<()> {
        for f in record.iter() {
            self.write_field(f)?;
        }
        self.write_terminator()
    }

    fn maybe_flush_buf(&mut self) -> io::Result<()> {
        if self.buf.len() >= BUF_SIZE {
            self.flush_buf()?;
        }
        Ok(())
    }

    fn flush_buf(&mut self) -> io::Result<()> {
        if self.buf.is_empty() {
            return Ok(());
        }
        let w = self.inner.as_mut().unwrap();
        let res = w.write_all(&self.buf);
        self.buf.clear();
        res
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.flush_buf()?;
        self.inner.as_mut().unwrap().flush()
    }

    /// Flushes and returns the underlying writer.
    pub fn into_inner(mut self) -> io::Result<W> {
        self.flush()?;
        Ok(self.inner.take().unwrap())
    }
}
