                        i,
                        first_record.len()
                    ))
                } else {
                    Ok(i - 1)
                }
            }
            OneSelector::IndexedName(ref s, sidx) => {
                if !use_names {
                    return Err(format!(
                        "Cannot use names ('{}') in selection with --no-headers set.",
                        s
                    ));
                }
                let mut num_found = 0;
                for (i, field) in first_record.iter().enumerate() {
                    if field == s.as_bytes() {
                        if num_found == sidx {
                            return Ok(i);
                        }
                        num_found += 1;
                    }
                }
                if num_found == 0 {
                    Err(format!(
                        "Selector name '{}' does not exist as a named header in the given CSV data.",
                        s
                    ))
                } else {
                    Err(format!(
                        "Selector index '{}' for name '{}' is out of bounds. Must be >= 0 and <= {}.",
                        sidx,
                        s,
                        num_found - 1
                    ))
                }
            }
        }
    }
