//! Shared configuration for reading and writing CSV data.

use std::fs;
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

use crate::csv::{self, ByteRecord, QuoteStyle, Reader, ReaderBuilder, Terminator, Writer, WriterBuilder};
use crate::index::Indexed;
use crate::select::{SelectColumns, Selection};
use crate::CliResult;

/// A single-byte field delimiter.
#[derive(Clone, Copy, Debug)]
pub struct Delimiter(pub u8);

impl Delimiter {
    pub fn as_byte(self) -> u8 {
        self.0
    }

    pub fn parse(s: &str) -> Result<Delimiter, String> {
        if s == r"\t" {
            return Ok(Delimiter(b'\t'));
        }
        if s.len() != 1 {
            return Err(format!("Could not convert '{}' to a single ASCII character.", s));
        }
        Ok(Delimiter(s.as_bytes()[0]))
    }
}

#[derive(Clone, Debug)]
pub struct Config {
    path: Option<PathBuf>,
    idx_path: Option<PathBuf>,
    select_columns: Option<SelectColumns>,
    delimiter: u8,
    pub no_headers: bool,
    flexible: bool,
    terminator: Terminator,
    quote: u8,
    quote_style: QuoteStyle,
    double_quote: bool,
    escape: Option<u8>,
    quoting: bool,
}

impl Config {
    pub fn new(path: &Option<String>) -> Config {
        let (path, idx_path) = match *path {
            None => (None, None),
            Some(ref s) if s == "-" => (None, None),
            Some(ref s) => {
                let p = PathBuf::from(s);
                let mut ip = s.clone();
                ip.push_str(".idx");
                (Some(p), Some(PathBuf::from(ip)))
            }
        };
        Config {
            path,
            idx_path,
            select_columns: None,
            delimiter: b',',
            no_headers: false,
            flexible: false,
            terminator: Terminator::Any(b'\n'),
            quote: b'"',
            quote_style: QuoteStyle::Necessary,
            double_quote: true,
            escape: None,
            quoting: true,
        }
    }

    pub fn delimiter(mut self, d: Option<Delimiter>) -> Config {
        if let Some(d) = d {
            self.delimiter = d.as_byte();
        }
        self
    }

    pub fn no_headers(mut self, yes: bool) -> Config {
        self.no_headers = yes;
        self
    }

    pub fn flexible(mut self, yes: bool) -> Config {
        self.flexible = yes;
        self
    }

    pub fn crlf(mut self, yes: bool) -> Config {
        if yes {
            self.terminator = Terminator::CRLF;
        } else {
            self.terminator = Terminator::Any(b'\n');
        }
        self
    }

    pub fn terminator(mut self, t: Terminator) -> Config {
        self.terminator = t;
        self
    }

    pub fn quote(mut self, q: u8) -> Config {
        self.quote = q;
        self
    }

    pub fn quote_style(mut self, s: QuoteStyle) -> Config {
        self.quote_style = s;
        self
    }

    pub fn double_quote(mut self, yes: bool) -> Config {
        self.double_quote = yes;
        self
    }

    pub fn escape(mut self, e: Option<u8>) -> Config {
        self.escape = e;
        self
    }

    pub fn quoting(mut self, yes: bool) -> Config {
        self.quoting = yes;
        self
    }

    pub fn select(mut self, sel: SelectColumns) -> Config {
        self.select_columns = Some(sel);
        self
    }

    pub fn is_std(&self) -> bool {
        self.path.is_none()
    }

    pub fn path(&self) -> Option<&PathBuf> {
        self.path.as_ref()
    }

    pub fn selection(&self, first_record: &ByteRecord) -> Result<Selection, String> {
        match self.select_columns {
            None => Err("Config has no 'SelectColums'. Did you call Config::select?".to_owned()),
            Some(ref sel) => sel.selection(first_record, !self.no_headers),
        }
    }

    pub fn write_headers<R: Read, W: Write>(&self, r: &mut Reader<R>, w: &mut Writer<W>) -> csv::Result<()> {
        if !self.no_headers {
            let r = r.byte_headers()?;
            if !r.is_empty() {
                w.write_record(r)?;
            }
        }
        Ok(())
    }

    pub fn writer(&self) -> io::Result<Writer<Box<dyn Write + 'static>>> {
        Ok(self.from_writer(self.io_writer()?))
    }

    pub fn io_writer(&self) -> io::Result<Box<dyn Write + 'static>> {
        Ok(match self.path {
            None => Box::new(io::stdout()),
            Some(ref p) => Box::new(fs::File::create(p)?),
        })
    }

    pub fn reader(&self) -> io::Result<Reader<Box<dyn Read + 'static>>> {
        Ok(self.from_reader(self.io_reader()?))
    }

    pub fn io_reader(&self) -> io::Result<Box<dyn Read + 'static>> {
        Ok(match self.path {
            None => Box::new(io::stdin()),
            Some(ref p) => match fs::File::open(p) {
                Ok(x) => Box::new(x),
                Err(err) => {
                    let msg = format!("failed to open {}: {}", p.display(), err);
                    return Err(io::Error::new(io::ErrorKind::NotFound, msg));
                }
            },
        })
    }

    pub fn reader_file(&self) -> io::Result<Reader<fs::File>> {
        match self.path {
            None => Err(io::Error::new(
                io::ErrorKind::Other,
                "Cannot use <stdin> here",
            )),
