//! A minimal docopt-style command line parser sufficient for xsv's usage
//! strings. Usage patterns and option descriptions are parsed from the doc
//! string itself.

use std::collections::HashMap;
use std::process;

#[derive(Clone, Debug)]
struct OptSpec {
    short: Option<char>,
    long: String,
    takes_arg: bool,
    default: Option<String>,
}

#[derive(Clone, Debug)]
enum PatElem {
    Cmd(String),
    Arg { name: String, optional: bool, repeated: bool },
    Options,
    Flag(String),
}

#[derive(Debug)]
pub enum DocoptError {
    /// A usage error: message plus the usage section. Exit code 1.
    Usage(String, String),
    /// A value could not be deserialized. Exit code 1, no usage printed.
    Deserialize(String),
    /// --help was requested; carries the full doc. Exit code 0.
    Help(String),
    /// --version was requested. Exit code 0.
    Version(String),
}

impl DocoptError {
    pub fn exit(&self) -> ! {
        match *self {
            DocoptError::Usage(ref msg, ref usage) => {
                eprintln!("{}\n\n{}", msg, usage);
                process::exit(1);
            }
            DocoptError::Deserialize(ref msg) => {
                eprintln!("{}", msg);
                process::exit(1);
            }
            DocoptError::Help(ref doc) => {
                println!("{}", doc.trim());
                process::exit(0);
            }
            DocoptError::Version(ref v) => {
                println!("{}", v);
                process::exit(0);
            }
        }
    }
}

#[derive(Clone, Debug)]
enum Value {
    Switch(bool),
    Plain(Option<String>),
    List(Vec<String>),
}

/// Parsed arguments.
#[derive(Clone, Debug)]
pub struct ArgvMap {
    map: HashMap<String, Value>,
}

impl ArgvMap {
    pub fn get_bool(&self, key: &str) -> bool {
        match self.map.get(key) {
            Some(Value::Switch(b)) => *b,
            Some(Value::Plain(Some(_))) => true,
            Some(Value::List(v)) => !v.is_empty(),
            _ => false,
        }
    }

    /// Returns the string value, or an empty string if absent.
    pub fn get_str(&self, key: &str) -> &str {
        match self.map.get(key) {
            Some(Value::Plain(Some(ref s))) => s,
            Some(Value::List(ref v)) if !v.is_empty() => &v[0],
            _ => "",
        }
    }

    pub fn get_opt_str(&self, key: &str) -> Option<String> {
        match self.map.get(key) {
            Some(Value::Plain(Some(ref s))) => Some(s.clone()),
            _ => None,
        }
    }

    pub fn get_vec(&self, key: &str) -> Vec<String> {
        match self.map.get(key) {
            Some(Value::List(ref v)) => v.clone(),
            Some(Value::Plain(Some(ref s))) => vec![s.clone()],
            _ => vec![],
        }
    }

    /// Deserializes an unsigned integer in the manner of docopt: empty
    /// (after trimming) values are zero.
    pub fn get_u64(&self, key: &str) -> Result<u64, DocoptError> {
        let s = self.get_str(key);
        parse_u64(s, key)
    }

    pub fn get_usize(&self, key: &str) -> Result<usize, DocoptError> {
        self.get_u64(key).map(|v| v as usize)
    }

    pub fn get_opt_u64(&self, key: &str) -> Result<Option<u64>, DocoptError> {
        match self.map.get(key) {
            Some(Value::Plain(Some(ref s))) => parse_u64(s, key).map(Some),
            _ => Ok(None),
        }
    }

    pub fn get_opt_usize(&self, key: &str) -> Result<Option<usize>, DocoptError> {
        self.get_opt_u64(key).map(|v| v.map(|x| x as usize))
    }
}

fn parse_u64(s: &str, key: &str) -> Result<u64, DocoptError> {
    if s.trim().is_empty() {
        return Ok(0);
    }
    match s.parse::<u64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(DocoptError::Deserialize(format!(
            "Could not deserialize '{}' to u64 for '{}'.",
            s, key
        ))),
    }
}

/// A parsed usage document.
pub struct Docopt {
    doc: String,
    usage: String,
    options: Vec<OptSpec>,
    patterns: Vec<Vec<PatElem>>,
    options_first: bool,
    version: Option<String>,
}

impl Docopt {
    pub fn new(doc: &str) -> Docopt {
        let usage = extract_usage(doc);
        let options = parse_options(doc);
        let patterns = parse_patterns(&usage, &options);
        Docopt {
            doc: doc.to_string(),
            usage,
            options,
            patterns,
            options_first: false,
            version: None,
        }
    }

    pub fn options_first(mut self, yes: bool) -> Docopt {
        self.options_first = yes;
        self
    }

    pub fn version(mut self, v: Option<String>) -> Docopt {
        self.version = v;
        self
    }

    fn find_long(&self, name: &str) -> Option<&OptSpec> {
        self.options.iter().find(|o| o.long == name)
    }

    fn find_short(&self, c: char) -> Option<&OptSpec> {
        self.options.iter().find(|o| o.short == Some(c))
    }

    fn usage_err(&self, msg: String) -> DocoptError {
        DocoptError::Usage(msg, self.usage.clone())
    }

    /// Parses the given arguments (excluding the program name).
    pub fn parse(&self, argv: &[String]) -> Result<ArgvMap, DocoptError> {
        // Tokenize.
        let mut positionals: Vec<String> = vec![];
        let mut flags: Vec<(String, Option<String>)> = vec![];
        let mut only_positional = false;
        let mut i = 0;
        while i < argv.len() {
            let a = &argv[i];
            i += 1;
            if only_positional {
                positionals.push(a.clone());
                continue;
            }
            if a == "--" {
                only_positional = true;
                continue;
            }
            if a.starts_with("--") {
                let (name, val) = match a.find('=') {
                    Some(eq) => (&a[..eq], Some(a[eq + 1..].to_string())),
                    None => (&a[..], None),
                };
                let opt = match self.find_long(name) {
                    None => return Err(self.usage_err(format!("Unknown flag: '{}'", name))),
                    Some(o) => o.clone(),
                };
                if opt.takes_arg {
                    let v = match val {
                        Some(v) => v,
                        None => {
                            if i < argv.len() {
                                i += 1;
                                argv[i - 1].clone()
                            } else {
                                return Err(self.usage_err(format!(
                                    "Expected argument for flag '{}' but reached end of arguments.",
                                    opt.long
                                )));
                            }
                        }
                    };
                    flags.push((opt.long.clone(), Some(v)));
                } else {
                    if let Some(v) = val {
                        return Err(self.usage_err(format!(
                            "Flag '{}' cannot have an argument, but found '{}'.",
                            opt.long, v
                        )));
                    }
                    flags.push((opt.long.clone(), None));
                }
                continue;
            }
            if a.starts_with('-') && a.len() > 1 {
                let chars: Vec<char> = a[1..].chars().collect();
                let mut j = 0;
                while j < chars.len() {
                    let c = chars[j];
                    j += 1;
                    let opt = match self.find_short(c) {
                        None => return Err(self.usage_err(format!("Unknown flag: '-{}'", c))),
                        Some(o) => o.clone(),
                    };
                    if opt.takes_arg {
                        let rest: String = chars[j..].iter().collect();
                        let v = if !rest.is_empty() {
                            rest
                        } else if i < argv.len() {
                            i += 1;
                            argv[i - 1].clone()
                        } else {
                            return Err(self.usage_err(format!(
                                "Expected argument for flag '{}' but reached end of arguments.",
                                opt.long
                            )));
                        };
                        flags.push((opt.long.clone(), Some(v)));
                        break;
                    } else {
                        flags.push((opt.long.clone(), None));
                    }
                }
                continue;
            }
            positionals.push(a.clone());
            if self.options_first {
                only_positional = true;
            }
        }

        // Count flags.
        let mut counts: HashMap<String, usize> = HashMap::new();
        for (name, _) in &flags {
            *counts.entry(name.clone()).or_insert(0) += 1;
        }

        // Try each pattern.
        let mut matched: Option<HashMap<String, Value>> = None;
        for pat in &self.patterns {
            if let Some(m) = self.match_pattern(pat, &positionals, &counts) {
                matched = Some(m);
                break;
            }
        }
        let mut map = match matched {
            None => return Err(self.usage_err("Invalid arguments.".to_string())),
            Some(m) => m,
        };

        // Fill in flag values.
        for opt in &self.options {
            if opt.takes_arg {
                let mut val: Option<String> = opt.default.clone();
                for (name, v) in &flags {
                    if *name == opt.long {
                        val = v.clone();
                    }
                }
                map.insert(opt.long.clone(), Value::Plain(val));
            } else {
                let present = counts.get(&opt.long).copied().unwrap_or(0) > 0;
                map.insert(opt.long.clone(), Value::Switch(present));
            }
        }

        let args = ArgvMap { map };
        if args.get_bool("--help") && self.find_long("--help").is_some() {
            return Err(DocoptError::Help(self.doc.clone()));
        }
        if let Some(ref v) = self.version {
            if args.get_bool("--version") && self.find_long("--version").is_some() {
                return Err(DocoptError::Version(v.clone()));
            }
        }
        Ok(args)
    }

    fn match_pattern(
        &self,
        pat: &[PatElem],
        positionals: &[String],
        counts: &HashMap<String, usize>,
    ) -> Option<HashMap<String, Value>> {
        let has_options = pat.iter().any(|e| matches!(e, PatElem::Options));
        let explicit: Vec<&str> = pat
            .iter()
            .filter_map(|e| match e {
                PatElem::Flag(ref f) => Some(f.as_str()),
                _ => None,
            })
            .collect();
        // Check flags.
        for opt in &self.options {
            let c = counts.get(&opt.long).copied().unwrap_or(0);
            if explicit.contains(&opt.long.as_str()) {
                if c != 1 {
                    return None;
                }
            } else if has_options {
                if c > 1 {
                    return None;
                }
            } else if c != 0 {
                return None;
            }
        }
        // Check positionals.
        let mut map: HashMap<String, Value> = HashMap::new();
        // Pre-populate all positional names and commands with empty values.
        for p in &self.patterns {
            for e in p {
                match e {
                    PatElem::Cmd(ref c) => {
                        map.entry(c.clone()).or_insert(Value::Switch(false));
                    }
                    PatElem::Arg { ref name, repeated, .. } => {
                        if *repeated {
                            map.entry(name.clone()).or_insert(Value::List(vec![]));
                        } else {
                            map.entry(name.clone()).or_insert(Value::Plain(None));
                        }
                    }
                    _ => {}
                }
            }
        }
        let mut idx = 0;
        for e in pat {
            match e {
                PatElem::Cmd(ref c) => {
                    if idx < positionals.len() && positionals[idx] == *c {
                        idx += 1;
                        map.insert(c.clone(), Value::Switch(true));
                    } else {
                        return None;
                    }
                }
                PatElem::Arg { ref name, optional, repeated } => {
                    if *repeated {
                        let rest: Vec<String> = positionals[idx..].to_vec();
                        if !*optional && rest.is_empty() {
                            return None;
                        }
                        idx = positionals.len();
                        map.insert(name.clone(), Value::List(rest));
                    } else if idx < positionals.len() {
                        map.insert(name.clone(), Value::Plain(Some(positionals[idx].clone())));
                        idx += 1;
                    } else if !*optional {
                        return None;
                    }
                }
                PatElem::Options | PatElem::Flag(_) => {}
            }
        }
        if idx != positionals.len() {
            return None;
        }
        Some(map)
    }
}

fn extract_usage(doc: &str) -> String {
    // Find "usage:" (case-insensitive) and take until a blank line.
    let lower = doc.to_lowercase();
    let start = match lower.find("usage:") {
        Some(i) => i,
        None => return String::new(),
    };
    let rest = &doc[start..];
    let mut end = rest.len();
    // A blank line terminates the section.
    let mut pos = 0;
    for line in rest.split_inclusive('\n') {
        if pos > 0 && line.trim().is_empty() {
            end = pos;
            break;
        }
        pos += line.len();
    }
    rest[..end].trim_end().to_string()
}

fn parse_options(doc: &str) -> Vec<OptSpec> {
    let mut opts: Vec<OptSpec> = vec![];
    // Skip the usage section when looking for options.
    let lower = doc.to_lowercase();
    let usage_start = lower.find("usage:").unwrap_or(0);
    let usage_len = extract_usage(doc).len();
    let after = &doc[usage_start + usage_len..];
    let lines: Vec<&str> = after.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_start();
        if trimmed.starts_with('-') {
            // Collect the description including continuation lines.
            let mut desc_lines = vec![line.to_string()];
            let mut j = i + 1;
            while j < lines.len() {
                let l = lines[j];
                let t = l.trim_start();
                if t.is_empty() || t.starts_with('-') {
                    break;
                }
                // A continuation line must be indented more than the option line.
                desc_lines.push(l.to_string());
                j += 1;
            }
            let full = desc_lines.join("\n");
            if let Some(spec) = parse_option_line(trimmed, &full) {
                opts.push(spec);
            }
            i = j;
        } else {
            i += 1;
        }
    }
    opts
}

fn parse_option_line(line: &str, full_desc: &str) -> Option<OptSpec> {
    // The option specification ends at the first run of two spaces.
    let spec_part = match line.find("  ") {
        Some(i) => &line[..i],
        None => line,
    };
    let mut short = None;
    let mut long = None;
    let mut takes_arg = false;
    for tok in spec_part.split(|c: char| c == ',' || c.is_whitespace()) {
        if tok.is_empty() {
            continue;
        }
        if let Some(l) = tok.strip_prefix("--") {
            let (name, arg) = match l.find('=') {
                Some(i) => (&l[..i], Some(&l[i + 1..])),
                None => (l, None),
            };
            long = Some(format!("--{}", name));
            if arg.is_some() {
                takes_arg = true;
            }
        } else if let Some(s) = tok.strip_prefix('-') {
            let mut cs = s.chars();
            if let Some(c) = cs.next() {
                short = Some(c);
                if cs.next().is_some() {
                    takes_arg = true;
                }
            }
        } else if tok.starts_with('<') || tok.chars().all(|c| c.is_uppercase() || c == '_') {
            takes_arg = true;
        }
    }
    let long = match long {
        Some(l) => l,
        None => match short {
            Some(c) => format!("-{}", c),
            None => return None,
        },
    };
    let mut default = None;
    let lower = full_desc.to_lowercase();
    if let Some(i) = lower.find("[default:") {
        let rest = &full_desc[i + "[default:".len()..];
        if let Some(j) = rest.find(']') {
            default = Some(rest[..j].trim().to_string());
        }
    }
    Some(OptSpec { short, long, takes_arg, default })
}

fn parse_patterns(usage: &str, options: &[OptSpec]) -> Vec<Vec<PatElem>> {
    let mut pats = vec![];
    let mut lines = usage.lines();
    // First line is "Usage:" possibly followed by a pattern on the same line.
    let first = lines.next().unwrap_or("");
    let mut pattern_lines: Vec<String> = vec![];
    if let Some(i) = first.to_lowercase().find("usage:") {
        let rest = first[i + 6..].trim();
        if !rest.is_empty() {
            pattern_lines.push(rest.to_string());
        }
    }
    for l in lines {
        let t = l.trim();
        if !t.is_empty() {
            pattern_lines.push(t.to_string());
        }
    }
    for pl in pattern_lines {
        let mut toks = pl.split_whitespace();
        toks.next(); // program name
        let mut elems = vec![];
        for tok in toks {
            if tok == "[options]" {
                elems.push(PatElem::Options);
            } else if tok == "[--]" || tok == "--" {
                // handled during tokenization
            } else if tok.starts_with("--") {
                let name = tok.trim_matches(|c| c == '[' || c == ']');
                let _ = options;
                elems.push(PatElem::Flag(name.to_string()));
            } else if tok.starts_with('[') {
                let inner = tok.trim_start_matches('[').trim_end_matches(']');
                let (inner, repeated) = match inner.strip_suffix("...") {
                    Some(x) => (x, true),
                    None => (inner, false),
                };
                if inner.starts_with('<') {
                    elems.push(PatElem::Arg { name: inner.to_string(), optional: true, repeated });
                } else {
                    elems.push(PatElem::Cmd(inner.to_string()));
                }
            } else if tok.starts_with('<') {
                let (inner, repeated) = match tok.strip_suffix("...") {
                    Some(x) => (x, true),
                    None => (tok, false),
                };
                elems.push(PatElem::Arg { name: inner.to_string(), optional: false, repeated });
            } else {
                elems.push(PatElem::Cmd(tok.to_string()));
            }
        }
        pats.push(elems);
    }
    pats
}
