//! A minimal docopt-style command line parser sufficient for xsv's usage
//! strings. Usage patterns and option descriptions are parsed from the doc
//! string itself.

use std::collections::HashMap;
use std::process;

#[derive(Clone, Debug)]
struct OptSpec {
    short: Option<char>,
    long: String,
    takes_arg: bool,
    default: Option<String>,
}

#[derive(Clone, Debug)]
enum PatElem {
    Cmd(String),
    Arg { name: String, optional: bool, repeated: bool },
    Options,
    Flag(String),
}

#[derive(Debug)]
pub enum DocoptError {
    /// A usage error: message plus the usage section. Exit code 1.
    Usage(String, String),
    /// A value could not be deserialized. Exit code 1, no usage printed.
    Deserialize(String),
    /// --help was requested; carries the full doc. Exit code 0.
    Help(String),
    /// --version was requested. Exit code 0.
    Version(String),
}

impl DocoptError {
    pub fn exit(&self) -> ! {
        match *self {
            DocoptError::Usage(ref msg, ref usage) => {
                eprintln!("{}\n\n{}", msg, usage);
                process::exit(1);
            }
            DocoptError::Deserialize(ref msg) => {
                eprintln!("{}", msg);
                process::exit(1);
            }
            DocoptError::Help(ref doc) => {
                println!("{}", doc.trim());
                process::exit(0);
            }
            DocoptError::Version(ref v) => {
                println!("{}", v);
                process::exit(0);
            }
        }
    }
}

#[derive(Clone, Debug)]
enum Value {
    Switch(bool),
    Plain(Option<String>),
    List(Vec<String>),
}

/// Parsed arguments.
#[derive(Clone, Debug)]
pub struct ArgvMap {
    map: HashMap<String, Value>,
}

impl ArgvMap {
    pub fn get_bool(&self, key: &str) -> bool {
        match self.map.get(key) {
            Some(Value::Switch(b)) => *b,
            Some(Value::Plain(Some(_))) => true,
            Some(Value::List(v)) => !v.is_empty(),
            _ => false,
        }
    }

    /// Returns the string value, or an empty string if absent.
    pub fn get_str(&self, key: &str) -> &str {
        match self.map.get(key) {
            Some(Value::Plain(Some(ref s))) => s,
            Some(Value::List(ref v)) if !v.is_empty() => &v[0],
            _ => "",
        }
    }

    pub fn get_opt_str(&self, key: &str) -> Option<String> {
        match self.map.get(key) {
            Some(Value::Plain(Some(ref s))) => Some(s.clone()),
            _ => None,
        }
    }

    pub fn get_vec(&self, key: &str) -> Vec<String> {
        match self.map.get(key) {
            Some(Value::List(ref v)) => v.clone(),
            Some(Value::Plain(Some(ref s))) => vec![s.clone()],
            _ => vec![],
        }
    }

    /// Deserializes an unsigned integer in the manner of docopt: empty
    /// (after trimming) values are zero.
    pub fn get_u64(&self, key: &str) -> Result<u64, DocoptError> {
        let s = self.get_str(key);
        parse_u64(s, key)
    }

    pub fn get_usize(&self, key: &str) -> Result<usize, DocoptError> {
        self.get_u64(key).map(|v| v as usize)
    }

    pub fn get_opt_u64(&self, key: &str) -> Result<Option<u64>, DocoptError> {
        match self.map.get(key) {
            Some(Value::Plain(Some(ref s))) => parse_u64(s, key).map(Some),
            _ => Ok(None),
        }
    }

    pub fn get_opt_usize(&self, key: &str) -> Result<Option<usize>, DocoptError> {
        self.get_opt_u64(key).map(|v| v.map(|x| x as usize))
    }
}

fn parse_u64(s: &str, key: &str) -> Result<u64, DocoptError> {
    if s.trim().is_empty() {
        return Ok(0);
    }
    match s.parse::<u64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(DocoptError::Deserialize(format!(
            "Could not deserialize '{}' to u64 for '{}'.",
            s, key
        ))),
    }
}

/// A parsed usage document.
pub struct Docopt {
    doc: String,
    usage: String,
    options: Vec<OptSpec>,
    patterns: Vec<Vec<PatElem>>,
    options_first: bool,
    version: Option<String>,
}

impl Docopt {
    pub fn new(doc: &str) -> Docopt {
        let usage = extract_usage(doc);
        let options = parse_options(doc);
        let patterns = parse_patterns(&usage, &options);
        Docopt {
            doc: doc.to_string(),
            usage,
            options,
            patterns,
            options_first: false,
            version: None,
        }
    }

    pub fn options_first(mut self, yes: bool) -> Docopt {
        self.options_first = yes;
