    fn usage_err(&self, msg: String) -> DocoptError {
        DocoptError::Usage(msg, self.usage.clone())
    }

    /// Parses the given arguments (excluding the program name).
    pub fn parse(&self, argv: &[String]) -> Result<ArgvMap, DocoptError> {
        // Tokenize.
        let mut positionals: Vec<String> = vec![];
        let mut flags: Vec<(String, Option<String>)> = vec![];
        let mut only_positional = false;
        let mut i = 0;
