                            map.entry(name.clone()).or_insert(Value::List(vec![]));
                        } else {
                            map.entry(name.clone()).or_insert(Value::Plain(None));
                        }
                    }
                    _ => {}
                }
            }
        }
        let mut idx = 0;
        for e in pat {
            match e {
                PatElem::Cmd(ref c) => {
                    if idx < positionals.len() && positionals[idx] == *c {
                        idx += 1;
                        map.insert(c.clone(), Value::Switch(true));
                    } else {
                        return None;
                    }
                }
                PatElem::Arg { ref name, optional, repeated } => {
                    if *repeated {
                        let rest: Vec<String> = positionals[idx..].to_vec();
                        if !*optional && rest.is_empty() {
                            return None;
                        }
                        idx = positionals.len();
                        map.insert(name.clone(), Value::List(rest));
                    } else if idx < positionals.len() {
                        map.insert(name.clone(), Value::Plain(Some(positionals[idx].clone())));
                        idx += 1;
                    } else if !*optional {
                        return None;
                    }
                }
                PatElem::Options | PatElem::Flag(_) => {}
            }
        }
        if idx != positionals.len() {
            return None;
        }
        Some(map)
    }
}

fn extract_usage(doc: &str) -> String {
    // Find "usage:" (case-insensitive) and take until a blank line.
    let lower = doc.to_lowercase();
    let start = match lower.find("usage:") {
        Some(i) => i,
        None => return String::new(),
    };
    let rest = &doc[start..];
    let mut end = rest.len();
    // A blank line terminates the section.
    let mut pos = 0;
    for line in rest.split_inclusive('\n') {
        if pos > 0 && line.trim().is_empty() {
            end = pos;
            break;
        }
        pos += line.len();
    }
    rest[..end].trim_end().to_string()
}

fn parse_options(doc: &str) -> Vec<OptSpec> {
    let mut opts: Vec<OptSpec> = vec![];
    // Skip the usage section when looking for options.
    let lower = doc.to_lowercase();
    let usage_start = lower.find("usage:").unwrap_or(0);
    let usage_len = extract_usage(doc).len();
    let after = &doc[usage_start + usage_len..];
    let lines: Vec<&str> = after.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_start();
        if trimmed.starts_with('-') {
            // Collect the description including continuation lines.
            let mut desc_lines = vec![line.to_string()];
            let mut j = i + 1;
            while j < lines.len() {
                let l = lines[j];
                let t = l.trim_start();
                if t.is_empty() || t.starts_with('-') {
                    break;
                }
                // A continuation line must be indented more than the option line.
                desc_lines.push(l.to_string());
                j += 1;
            }
            let full = desc_lines.join("\n");
            if let Some(spec) = parse_option_line(trimmed, &full) {
                opts.push(spec);
            }
            i = j;
        } else {
            i += 1;
        }
    }
    opts
}

fn parse_option_line(line: &str, full_desc: &str) -> Option<OptSpec> {
    // The option specification ends at the first run of two spaces.
    let spec_part = match line.find("  ") {
        Some(i) => &line[..i],
        None => line,
    };
    let mut short = None;
    let mut long = None;
    let mut takes_arg = false;
    for tok in spec_part.split(|c: char| c == ',' || c.is_whitespace()) {
        if tok.is_empty() {
            continue;
        }
        if let Some(l) = tok.strip_prefix("--") {
            let (name, arg) = match l.find('=') {
                Some(i) => (&l[..i], Some(&l[i + 1..])),
                None => (l, None),
            };
            long = Some(format!("--{}", name));
            if arg.is_some() {
                takes_arg = true;
            }
        } else if let Some(s) = tok.strip_prefix('-') {
            let mut cs = s.chars();
            if let Some(c) = cs.next() {
                short = Some(c);
                if cs.next().is_some() {
                    takes_arg = true;
                }
            }
        } else if tok.starts_with('<') || tok.chars().all(|c| c.is_uppercase() || c == '_') {
            takes_arg = true;
        }
    }
    let long = match long {
        Some(l) => l,
        None => match short {
            Some(c) => format!("-{}", c),
            None => return None,
        },
    };
    let mut default = None;
    let lower = full_desc.to_lowercase();
    if let Some(i) = lower.find("[default:") {
        let rest = &full_desc[i + "[default:".len()..];
        if let Some(j) = rest.find(']') {
            default = Some(rest[..j].trim().to_string());
        }
    }
    Some(OptSpec { short, long, takes_arg, default })
}

fn parse_patterns(usage: &str, options: &[OptSpec]) -> Vec<Vec<PatElem>> {
    let mut pats = vec![];
    let mut lines = usage.lines();
    // First line is "Usage:" possibly followed by a pattern on the same line.
    let first = lines.next().unwrap_or("");
    let mut pattern_lines: Vec<String> = vec![];
    if let Some(i) = first.to_lowercase().find("usage:") {
        let rest = first[i + 6..].trim();
        if !rest.is_empty() {
            pattern_lines.push(rest.to_string());
        }
    }
    for l in lines {
        let t = l.trim();
        if !t.is_empty() {
            pattern_lines.push(t.to_string());
        }
    }
    for pl in pattern_lines {
        let mut toks = pl.split_whitespace();
        toks.next(); // program name
        let mut elems = vec![];
        for tok in toks {
            if tok == "[options]" {
                elems.push(PatElem::Options);
            } else if tok == "[--]" || tok == "--" {
                // handled during tokenization
            } else if tok.starts_with("--") {
                let name = tok.trim_matches(|c| c == '[' || c == ']');
                let _ = options;
                elems.push(PatElem::Flag(name.to_string()));
            } else if tok.starts_with('[') {
                let inner = tok.trim_start_matches('[').trim_end_matches(']');
                let (inner, repeated) = match inner.strip_suffix("...") {
                    Some(x) => (x, true),
                    None => (inner, false),
                };
                if inner.starts_with('<') {
                    elems.push(PatElem::Arg { name: inner.to_string(), optional: true, repeated });
                } else {
                    elems.push(PatElem::Cmd(inner.to_string()));
                }
            } else if tok.starts_with('<') {
                let (inner, repeated) = match tok.strip_suffix("...") {
                    Some(x) => (x, true),
                    None => (tok, false),
                };
                elems.push(PatElem::Arg { name: inner.to_string(), optional: false, repeated });
            } else {
                elems.push(PatElem::Cmd(tok.to_string()));
            }
        }
        pats.push(elems);
    }
    pats
}
EOF
