//! Assorted helpers shared by commands.

use std::borrow::Cow;
use std::str;

use crate::config::{Config, Delimiter};
use crate::docopt::{ArgvMap, Docopt};
use crate::CliResult;

pub fn get_args(usage: &str, argv: &[String]) -> CliResult<ArgvMap> {
    Ok(Docopt::new(usage).parse(argv)?)
}

pub fn delimiter(args: &ArgvMap) -> CliResult<Option<Delimiter>> {
    match args.get_opt_str("--delimiter") {
        None => Ok(None),
        Some(s) => Ok(Some(Delimiter::parse(&s)?)),
    }
}

pub fn single_byte(args: &ArgvMap, key: &str) -> CliResult<Option<u8>> {
    match args.get_opt_str(key) {
        None => Ok(None),
        Some(s) => Ok(Some(Delimiter::parse(&s)?.as_byte())),
    }
}

pub fn opt_string(args: &ArgvMap, key: &str) -> Option<String> {
    args.get_opt_str(key)
}

pub fn num_cpus() -> usize {
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
}

pub fn njobs(flag_jobs: usize) -> usize {
    if flag_jobs == 0 {
        num_cpus()
    } else {
        flag_jobs
    }
}

pub fn chunk_size(nitems: usize, njobs: usize) -> usize {
    if nitems < njobs {
        nitems
    } else {
        nitems / njobs
    }
}

pub fn num_of_chunks(nitems: usize, chunk_size: usize) -> usize {
    if chunk_size == 0 {
        return nitems;
    }
    let mut n = nitems / chunk_size;
    if nitems % chunk_size != 0 {
        n += 1;
    }
    n
}

pub fn condense(val: Cow<[u8]>, n: Option<usize>) -> Cow<[u8]> {
    match n {
        None => val,
        Some(n) => {
            let mut is_short_utf8 = false;
            if let Ok(s) = str::from_utf8(&val) {
                if n >= s.chars().count() {
                    is_short_utf8 = true;
                } else {
                    let mut s: String = s.chars().take(n).collect();
                    s.push_str("...");
                    return Cow::Owned(s.into_bytes());
                }
            }
            if is_short_utf8 || n >= val.len() {
                val
            } else {
                let mut v = val[0..n].to_vec();
                v.extend_from_slice(b"...");
                Cow::Owned(v)
            }
        }
    }
}

pub fn range(
    start: Option<usize>,
    end: Option<usize>,
    len: Option<usize>,
    index: Option<usize>,
) -> Result<(usize, usize), String> {
    match (start, end, len, index) {
        (None, None, None, Some(i)) => Ok((i, i.wrapping_add(1))),
        (_, _, _, Some(_)) => Err("--index cannot be used with --start, --end or --len".to_owned()),
        (_, Some(_), Some(_), None) => {
            Err("--end and --len cannot be used at the same time.".to_owned())
        }
        (_, None, None, None) => Ok((start.unwrap_or(0), usize::MAX)),
        (_, Some(e), None, None) => {
            let s = start.unwrap_or(0);
            if s > e {
                Err(format!(
                    "The end of the range ({}) must be greater than or\n\
                     equal to the start of the range ({}).",
                    e, s
                ))
            } else {
                Ok((s, e))
            }
        }
        (_, None, Some(l), None) => {
            let s = start.unwrap_or(0);
            Ok((s, s.wrapping_add(l)))
        }
    }
}

pub fn many_configs(
    inps: &[String],
    delim: Option<Delimiter>,
    no_headers: bool,
