//! Elastic tabstop alignment of tab separated text.

use std::cmp;
use std::io::{self, Write};
use std::str;

use unicode_width::UnicodeWidthStr;

#[derive(Clone, Debug)]
struct Cell {
    start: usize,
    size: usize,
    width: usize,
}

/// Buffers writes and aligns columns (separated by `\t`) when flushed.
pub struct TabWriter<W: Write> {
    w: W,
    buf: Vec<u8>,
    lines: Vec<Vec<Cell>>,
    curcell: Cell,
    minwidth: usize,
    padding: usize,
}

impl<W: Write> TabWriter<W> {
    pub fn new(w: W) -> TabWriter<W> {
        TabWriter {
            w,
            buf: Vec::with_capacity(1024),
            lines: vec![vec![]],
            curcell: Cell { start: 0, size: 0, width: 0 },
            minwidth: 2,
            padding: 2,
        }
    }

    pub fn minwidth(mut self, minwidth: usize) -> TabWriter<W> {
        self.minwidth = minwidth;
        self
    }

    pub fn padding(mut self, padding: usize) -> TabWriter<W> {
        self.padding = padding;
        self
    }

    fn add_bytes(&mut self, bytes: &[u8]) {
        self.curcell.size += bytes.len();
        self.buf.extend_from_slice(bytes);
    }

    fn term_curcell(&mut self) {
        let mut cell = Cell { start: self.buf.len(), size: 0, width: 0 };
        std::mem::swap(&mut cell, &mut self.curcell);
        cell.width = cell_width(&self.buf[cell.start..cell.start + cell.size]);
        self.lines.last_mut().unwrap().push(cell);
    }

    fn reset(&mut self) {
        self.buf.clear();
        self.lines = vec![vec![]];
        self.curcell = Cell { start: 0, size: 0, width: 0 };
    }
}

fn cell_width(bytes: &[u8]) -> usize {
    match str::from_utf8(bytes) {
        Ok(s) => UnicodeWidthStr::width(s),
        Err(_) => bytes.len(),
    }
}

impl<W: Write> Write for TabWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let mut last = 0;
        for (i, &b) in buf.iter().enumerate() {
            match b {
                b'\t' | b'\n' => {
                    self.add_bytes(&buf[last..i]);
                    self.term_curcell();
                    last = i + 1;
                    if b == b'\n' {
                        self.lines.push(vec![]);
                    }
                }
                _ => {}
            }
        }
        self.add_bytes(&buf[last..]);
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        if self.curcell.size > 0 {
            self.term_curcell();
        }
        let widths = self.column_widths();
        let mut nlines = self.lines.len();
        // The final line is only "real" if it has cells.
        if self.lines.last().map_or(false, |l| l.is_empty()) {
            nlines -= 1;
        }
        for (i, line) in self.lines.iter().enumerate().take(nlines) {
            for (j, cell) in line.iter().enumerate() {
                let bytes = &self.buf[cell.start..cell.start + cell.size];
                self.w.write_all(bytes)?;
                if j < widths[i].len() {
                    let pad = widths[i][j].saturating_sub(cell.width);
                    for _ in 0..pad {
                        self.w.write_all(b" ")?;
                    }
                }
            }
            if i + 1 < self.lines.len() {
                self.w.write_all(b"\n")?;
            }
        }
        self.reset();
        self.w.flush()
    }
}

impl<W: Write> TabWriter<W> {
    fn column_widths(&self) -> Vec<Vec<usize>> {
        let mut ws: Vec<Vec<usize>> = vec![vec![]; self.lines.len()];
        for (i, iline) in self.lines.iter().enumerate() {
            if iline.is_empty() {
                continue;
            }
            // The last cell of a line is not aligned.
            let ncols = iline.len() - 1;
            for col in ws[i].len()..ncols {
                let mut width = self.minwidth;
                let mut contig = 0;
                for line in self.lines[i..].iter() {
                    if col + 1 >= line.len() {
                        break;
                    }
                    contig += 1;
                    width = cmp::max(width, line[col].width);
                }
                let width = width + self.padding;
                for j in i..i + contig {
                    ws[j].push(width);
                }
            }
        }
        ws
    }
}
