                           as headers. When set, the name of each field
                           will be its index.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(argv: &[String]) -> CliResult<()> {
    let args = util::get_args(USAGE, argv)?;
    let condense = args.get_opt_usize("--condense")?;
    let separator = args.get_str("--separator").to_string();
    let rconfig = Config::new(&args.get_opt_str("<input>"))
        .delimiter(util::delimiter(&args)?)
        .no_headers(args.get_bool("--no-headers"));
    let mut rdr = rconfig.reader()?;
    let headers = rdr.byte_headers()?.clone();

    let mut wtr = TabWriter::new(io::stdout());
    let mut first = true;
    let mut record = ByteRecord::new();
    while rdr.read_byte_record(&mut record)? {
        if !first && !separator.is_empty() {
            writeln!(&mut wtr, "{}", separator)?;
        }
        first = false;
        for (i, (header, field)) in headers.iter().zip(record.iter()).enumerate() {
            if rconfig.no_headers {
                write!(&mut wtr, "{}", i)?;
            } else {
                wtr.write_all(header)?;
            }
            wtr.write_all(b"\t")?;
            wtr.write_all(&util::condense(Cow::Borrowed(field), condense))?;
            wtr.write_all(b"\n")?;
        }
    }
    wtr.flush()?;
    Ok(())
}
