use std::borrow::Cow;

use crate::config::{Config, Delimiter};
use crate::csv::ByteRecord;
use crate::tabwriter::TabWriter;
use crate::util;
use crate::CliResult;

static USAGE: &str = "
Outputs CSV data as a table with columns in alignment.

This will not work well if the CSV data contains large fields.

Note that formatting a table requires buffering all CSV data into memory.
Therefore, you should use the 'sample' or 'slice' command to trim down large
CSV data before formatting it with this command.

Usage:
    xsv table [options] [<input>]

table options:
    -w, --width <arg>      The minimum width of each column.
                           [default: 2]
    -p, --pad <arg>        The minimum number of spaces between each column.
                           [default: 2]
    -c, --condense <arg>  Limits the length of each field to the value
                           specified. If the field is UTF-8 encoded, then
                           <arg> refers to the number of code points.
                           Otherwise, it refers to the number of bytes.

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(argv: &[String]) -> CliResult<()> {
    let args = util::get_args(USAGE, argv)?;
    let width = args.get_usize("--width")?;
    let pad = args.get_usize("--pad")?;
    let condense = args.get_opt_usize("--condense")?;
    let rconfig = Config::new(&args.get_opt_str("<input>"))
        .delimiter(util::delimiter(&args)?)
        .no_headers(true);
    let wconfig = Config::new(&args.get_opt_str("--output")).delimiter(Some(Delimiter(b'\t')));

    let tw = TabWriter::new(wconfig.io_writer()?).minwidth(width).padding(pad);
    let mut wtr = wconfig.from_writer(tw);
    let mut rdr = rconfig.reader()?;

    let mut record = ByteRecord::new();
    while rdr.read_byte_record(&mut record)? {
        wtr.write_record(record.iter().map(|f| util::condense(Cow::Borrowed(f), condense)))?;
    }
    wtr.flush()?;
    Ok(())
}
EOF
