    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. Namely, it will be sorted with the rest
                           of the rows. Otherwise, the first row will always
                           appear as the header row in the output.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(argv: &[String]) -> CliResult<()> {
    let args = util::get_args(USAGE, argv)?;
    let numeric = args.get_bool("--numeric");
    let reverse = args.get_bool("--reverse");
    let selection = match args.get_opt_str("--select") {
        None => SelectColumns::parse("")?,
        Some(s) => SelectColumns::parse(&s)?,
    };
    let rconfig = Config::new(&args.get_opt_str("<input>"))
        .delimiter(util::delimiter(&args)?)
        .no_headers(args.get_bool("--no-headers"))
        .select(selection);

    let mut rdr = rconfig.reader()?;
    let mut wtr = Config::new(&args.get_opt_str("--output")).writer()?;

    let headers = rdr.byte_headers()?.clone();
    let sel = rconfig.selection(&headers)?;

    let mut all = rdr.byte_records().collect::<Result<Vec<_>, _>>()?;
    match (numeric, reverse) {
        (false, false) => all.sort_by(|r1, r2| {
            let a = sel.select(r1);
            let b = sel.select(r2);
            iter_cmp(a, b)
        }),
        (true, false) => all.sort_by(|r1, r2| {
            let a = sel.select(r1);
            let b = sel.select(r2);
            iter_cmp_num(a, b)
        }),
        (false, true) => all.sort_by(|r1, r2| {
            let a = sel.select(r1);
            let b = sel.select(r2);
            iter_cmp(b, a)
        }),
        (true, true) => all.sort_by(|r1, r2| {
            let a = sel.select(r1);
            let b = sel.select(r2);
            iter_cmp_num(b, a)
        }),
    }

    rconfig.write_headers(&mut rdr, &mut wtr)?;
    for r in all.into_iter() {
        wtr.write_byte_record(&r)?;
    }
    wtr.flush()?;
