use std::collections::HashMap;
use std::fs;
use std::io;
use std::sync::mpsc;
use std::thread;

use crate::config::{Config, Delimiter};
use crate::csv::ByteRecord;
use crate::index::Indexed;
use crate::select::{SelectColumns, Selection};
use crate::util;
use crate::CliResult;

static USAGE: &str = "
Compute a frequency table on CSV data.

The frequency table is formatted as CSV data:

    field,value,count

By default, there is a row for the N most frequent values for each field in the
data. The order and number of values can be tweaked with --asc and --limit,
respectively.

Since this computes an exact frequency table, memory proportional to the
cardinality of each column is required.

Usage:
    xsv frequency [options] [<input>]

frequency options:
    -s, --select <arg>     Select a subset of columns to compute frequencies
                           for. See 'xsv select --help' for the format
                           details. This is provided here because piping 'xsv
                           select' into 'xsv frequency' will disable the use
                           of indexing.
    -l, --limit <arg>      Limit the frequency table to the N most common
                           items. Set to '0' to disable a limit.
                           [default: 10]
    -a, --asc              Sort the frequency tables in ascending order by
                           count. The default is descending order.
    --no-nulls             Don't include NULLs in the frequency table.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be included
                           in the frequency table. Additionally, the 'field'
                           column will be 1-based indices instead of header
                           names.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Clone)]
struct Args {
    arg_input: Option<String>,
    flag_select: SelectColumns,
    flag_limit: usize,
    flag_asc: bool,
    flag_no_nulls: bool,
    flag_jobs: usize,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<Delimiter>,
}

/// A frequency table preserving first-insertion order for ties.
#[derive(Clone, Default)]
pub struct Frequencies {
    map: HashMap<Vec<u8>, (usize, u64)>,
    order: Vec<Vec<u8>>,
}

impl Frequencies {
    pub fn new() -> Frequencies {
        Frequencies::default()
    }

    pub fn add(&mut self, v: Vec<u8>) {
        self.add_count(v, 1);
    }

    pub fn add_count(&mut self, v: Vec<u8>, n: u64) {
        if let Some(e) = self.map.get_mut(&v) {
            e.1 += n;
        } else {
            let idx = self.order.len();
            self.order.push(v.clone());
            self.map.insert(v, (idx, n));
        }
    }

    pub fn merge(&mut self, other: Frequencies) {
        for k in other.order {
            let (_, c) = other.map[&k];
            self.add_count(k, c);
        }
    }

    pub fn cardinality(&self) -> u64 {
        self.map.len() as u64
    }

    fn counts(&self) -> Vec<(&[u8], u64)> {
        self.order
            .iter()
            .map(|k| (k.as_slice(), self.map[k].1))
            .collect()
    }

    pub fn most_frequent(&self) -> Vec<(&[u8], u64)> {
        let mut v = self.counts();
        v.sort_by(|a, b| b.1.cmp(&a.1));
        v
    }

    pub fn least_frequent(&self) -> Vec<(&[u8], u64)> {
        let mut v = self.counts();
        v.sort_by(|a, b| a.1.cmp(&b.1));
        v
    }
}

type FTables = Vec<Frequencies>;

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = util::get_args(USAGE, argv)?;
    let args = Args {
        arg_input: a.get_opt_str("<input>"),
        flag_select: match a.get_opt_str("--select") {
            None => SelectColumns::parse("")?,
            Some(s) => SelectColumns::parse(&s)?,
        },
        flag_limit: a.get_usize("--limit")?,
        flag_asc: a.get_bool("--asc"),
        flag_no_nulls: a.get_bool("--no-nulls"),
        flag_jobs: a.get_usize("--jobs")?,
        flag_output: a.get_opt_str("--output"),
        flag_no_headers: a.get_bool("--no-headers"),
        flag_delimiter: util::delimiter(&a)?,
    };
    let rconfig = args.rconfig();

    let mut wtr = Config::new(&args.flag_output).writer()?;
    let (headers, tables) = match args.rconfig().indexed()? {
        Some(ref mut idx) if args.njobs() > 1 => args.parallel_ftables(idx),
        _ => args.sequential_ftables(),
    }?;

    wtr.write_record(vec![&b"field"[..], &b"value"[..], &b"count"[..]])?;
    let head_ftables = headers.into_iter().zip(tables.into_iter());
    for (i, (header, ftab)) in head_ftables.enumerate() {
        let mut header = header.to_vec();
        if rconfig.no_headers {
            header = (i + 1).to_string().into_bytes();
        }
        for (value, count) in args.counts(&ftab).into_iter() {
            let count = count.to_string();
            let row = vec![&*header, &*value, count.as_bytes()];
            wtr.write_record(row)?;
        }
    }
    wtr.flush()?;
    Ok(())
}

impl Args {
    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.flag_select.clone())
    }

    fn counts(&self, ftab: &Frequencies) -> Vec<(Vec<u8>, u64)> {
        let mut counts = if self.flag_asc {
            ftab.least_frequent()
        } else {
            ftab.most_frequent()
        };
        if self.flag_limit > 0 {
            counts.truncate(self.flag_limit);
        }
        counts
            .into_iter()
            .map(|(bs, c)| {
                if b"" == bs {
                    (b"(NULL)".to_vec(), c)
                } else {
                    (bs.to_vec(), c)
                }
            })
            .collect()
    }

    fn sequential_ftables(&self) -> CliResult<(Vec<Vec<u8>>, FTables)> {
        let mut rdr = self.rconfig().reader()?;
        let (headers, sel) = self.sel_headers(&mut rdr)?;
        Ok((headers, self.ftables(&sel, rdr.byte_records())?))
    }

    fn parallel_ftables(
        &self,
        idx: &mut Indexed<fs::File, fs::File>,
    ) -> CliResult<(Vec<Vec<u8>>, FTables)> {
        let (headers, sel) = self.sel_headers(&mut **idx)?;

        if idx.count() == 0 {
            return Ok((headers, vec![]));
        }

        let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
        let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);

        let (send, recv) = mpsc::channel();
        let mut handles = vec![];
        for i in 0..nchunks {
            let (send, args, sel) = (send.clone(), self.clone(), sel.clone());
            handles.push(thread::spawn(move || {
                let mut idx = args.rconfig().indexed().unwrap().unwrap();
                idx.seek((i * chunk_size) as u64).unwrap();
                let it = idx.byte_records().take(chunk_size);
                send.send(args.ftables(&sel, it).unwrap()).unwrap();
            }));
        }
        drop(send);
        let mut merged: Option<FTables> = None;
        for tables in recv.iter() {
            merged = Some(match merged {
                None => tables,
                Some(mut acc) => {
                    for (a, b) in acc.iter_mut().zip(tables.into_iter()) {
                        a.merge(b);
                    }
                    acc
                }
            });
        }
        for h in handles {
            let _ = h.join();
        }
        Ok((headers, merged.unwrap_or_default()))
    }

    fn ftables<I>(&self, sel: &Selection, it: I) -> CliResult<FTables>
    where
        I: Iterator<Item = crate::csv::Result<ByteRecord>>,
    {
        let null = b"".to_vec();
        let nsel = sel.normal();
        let mut tabs: Vec<_> = (0..nsel.len()).map(|_| Frequencies::new()).collect();
        for row in it {
            let row = row?;
            for (i, field) in nsel.select(&row).enumerate() {
                let field = util::trim_bytes(field.to_vec());
                if !field.is_empty() {
                    tabs[i].add(field);
                } else if !self.flag_no_nulls {
                    tabs[i].add(null.clone());
                }
            }
        }
        Ok(tabs)
    }

    fn sel_headers<R: io::Read>(
        &self,
        rdr: &mut crate::csv::Reader<R>,
    ) -> CliResult<(Vec<Vec<u8>>, Selection)> {
        let headers = rdr.byte_headers()?.clone();
        let sel = self.rconfig().selection(&headers)?;
        Ok((sel.select(&headers).map(|h| h.to_vec()).collect(), sel))
    }

    fn njobs(&self) -> usize {
        util::njobs(self.flag_jobs)
    }
}
