/// A frequency table preserving first-insertion order for ties.
#[derive(Clone, Default)]
pub struct Frequencies {
    map: HashMap<Vec<u8>, (usize, u64)>,
    order: Vec<Vec<u8>>,
}

impl Frequencies {
    pub fn new() -> Frequencies {
        Frequencies::default()
    }

    pub fn add(&mut self, v: Vec<u8>) {
        self.add_count(v, 1);
    }

    pub fn add_count(&mut self, v: Vec<u8>, n: u64) {
        if let Some(e) = self.map.get_mut(&v) {
            e.1 += n;
        } else {
            let idx = self.order.len();
            self.order.push(v.clone());
            self.map.insert(v, (idx, n));
        }
    }

    pub fn merge(&mut self, other: Frequencies) {
        for k in other.order {
            let (_, c) = other.map[&k];
            self.add_count(k, c);
        }
    }

    pub fn cardinality(&self) -> u64 {
        self.map.len() as u64
    }

    fn counts(&self) -> Vec<(&[u8], u64)> {
        self.order
            .iter()
            .map(|k| (k.as_slice(), self.map[k].1))
            .collect()
    }

    pub fn most_frequent(&self) -> Vec<(&[u8], u64)> {
        let mut v = self.counts();
        v.sort_by(|a, b| b.1.cmp(&a.1));
        v
    }

    pub fn least_frequent(&self) -> Vec<(&[u8], u64)> {
        let mut v = self.counts();
        v.sort_by(|a, b| a.1.cmp(&b.1));
        v
    }
}

