use crate::util;
use crate::CliResult;

static USAGE: &str = "
Computes basic statistics on CSV data.

Basic statistics includes mean, median, mode, standard deviation, sum, max and
min values. Note that some statistics are expensive to compute, so they must
be enabled explicitly. By default, the following statistics are reported for
*every* column in the CSV data: mean, max, min and standard deviation. The
default set of statistics corresponds to statistics that can be computed
efficiently on a stream of data (i.e., constant memory).

Computing statistics on a large file can be made much faster if you create
an index for it first with 'xsv index'.

Usage:
    xsv stats [options] [<input>]

stats options:
    -s, --select <arg>     Select a subset of columns to compute stats for.
                           See 'xsv select --help' for the format details.
                           This is provided here because piping 'xsv select'
                           into 'xsv stats' will disable the use of indexing.
    --everything           Show all statistics available.
    --mode                 Show the mode.
                           This requires storing all CSV data in memory.
    --cardinality          Show the cardinality.
                           This requires storing all CSV data in memory.
    --median               Show the median.
                           This requires storing all CSV data in memory.
    --nulls                Include NULLs in the population size for computing
                           mean and standard deviation.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. i.e., They will be included
                           in statistics.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Clone)]
struct Args {
    arg_input: Option<String>,
    flag_select: SelectColumns,
    flag_everything: bool,
    flag_mode: bool,
    flag_cardinality: bool,
    flag_median: bool,
    flag_nulls: bool,
    flag_jobs: usize,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<Delimiter>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = util::get_args(USAGE, argv)?;
    let args = Args {
        arg_input: a.get_opt_str("<input>"),
        flag_select: match a.get_opt_str("--select") {
            None => SelectColumns::parse("")?,
            Some(s) => SelectColumns::parse(&s)?,
        },
        flag_everything: a.get_bool("--everything"),
        flag_mode: a.get_bool("--mode"),
        flag_cardinality: a.get_bool("--cardinality"),
        flag_median: a.get_bool("--median"),
        flag_nulls: a.get_bool("--nulls"),
        flag_jobs: a.get_usize("--jobs")?,
        flag_output: a.get_opt_str("--output"),
        flag_no_headers: a.get_bool("--no-headers"),
        flag_delimiter: util::delimiter(&a)?,
    };

    let mut wtr = Config::new(&args.flag_output).writer()?;
    let (headers, stats) = match args.rconfig().indexed()? {
        None => args.sequential_stats(),
        Some(idx) => {
            if args.njobs() == 1 {
                args.sequential_stats()
            } else {
                args.parallel_stats(idx)
            }
        }
    }?;
    let stats = args.stats_to_records(stats);

    wtr.write_record(&args.stat_headers())?;
    let fields = headers.iter().zip(stats.into_iter());
    for (i, (header, stat)) in fields.enumerate() {
        let header = if args.flag_no_headers {
            i.to_string().into_bytes()
        } else {
            header.to_vec()
        };
        let stat = stat.iter().map(|f| f.as_bytes());
        wtr.write_record(vec![&*header].into_iter().chain(stat))?;
    }
    wtr.flush()?;
    Ok(())
}

impl Args {
    fn sequential_stats(&self) -> CliResult<(ByteRecord, Vec<Stats>)> {
        let mut rdr = self.rconfig().reader()?;
        let (headers, sel) = self.sel_headers(&mut rdr)?;
        let stats = self.compute(&sel, rdr.byte_records())?;
        Ok((headers, stats))
    }

    fn parallel_stats(
        &self,
        mut idx: Indexed<fs::File, fs::File>,
    ) -> CliResult<(ByteRecord, Vec<Stats>)> {
        // N.B. This is probably more complicated than it needs to be.
        if idx.count() == 0 {
            return self.sequential_stats();
        }

        let (headers, sel) = self.sel_headers(&mut *idx)?;

        let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
        let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);

        let mut handles = vec![];
        for i in 0..nchunks {
            let (args, sel) = (self.clone(), sel.clone());
            handles.push(thread::spawn(move || -> CliResult<Vec<Stats>> {
                let mut idx = args.rconfig().indexed()?.unwrap();
                idx.seek((i * chunk_size) as u64)?;
                let it = idx.byte_records().take(chunk_size);
                args.compute(&sel, it)
            }));
        }
        let mut merged: Option<Vec<Stats>> = None;
        for h in handles {
            let stats = h.join().expect("thread panicked")?;
            merged = Some(match merged {
                None => stats,
                Some(mut acc) => {
                    for (a, b) in acc.iter_mut().zip(stats.into_iter()) {
                        a.merge(b);
                    }
                    acc
                }
            });
        }
        Ok((headers, merged.unwrap_or_default()))
    }

    fn stats_to_records(&self, stats: Vec<Stats>) -> Vec<Vec<String>> {
        stats.into_iter().map(|s| s.to_record()).collect()
    }

    fn compute<I>(&self, sel: &Selection, it: I) -> CliResult<Vec<Stats>>
    where
        I: Iterator<Item = crate::csv::Result<ByteRecord>>,
    {
        let mut stats = self.new_stats(sel.len());
        for row in it {
            let row = row?;
            for (i, field) in sel.select(&row).enumerate() {
                stats[i].add(field);
            }
        }
        Ok(stats)
    }

    fn sel_headers<R: io::Read>(
        &self,
        rdr: &mut crate::csv::Reader<R>,
    ) -> CliResult<(ByteRecord, Selection)> {
        let headers = rdr.byte_headers()?.clone();
        let sel = self.rconfig().selection(&headers)?;
        Ok((ByteRecord::from_fields(sel.select(&headers)), sel))
    }

    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.flag_select.clone())
    }

    fn njobs(&self) -> usize {
        util::njobs(self.flag_jobs)
    }

    fn new_stats(&self, record_len: usize) -> Vec<Stats> {
        repeat(Stats::new(WhichStats {
            include_nulls: self.flag_nulls,
            sum: true,
            range: true,
            dist: true,
            cardinality: self.flag_cardinality || self.flag_everything,
            median: self.flag_median || self.flag_everything,
            mode: self.flag_mode || self.flag_everything,
        }))
        .take(record_len)
        .collect()
    }

    fn stat_headers(&self) -> ByteRecord {
        let mut fields = vec![
            "field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev",
        ];
        let all = self.flag_everything;
        if self.flag_median || all {
            fields.push("median");
        }
        if self.flag_mode || all {
            fields.push("mode");
        }
        if self.flag_cardinality || all {
            fields.push("cardinality");
        }
        ByteRecord::from_fields(fields)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct WhichStats {
    include_nulls: bool,
    sum: bool,
    range: bool,
    dist: bool,
    cardinality: bool,
    median: bool,
    mode: bool,
}

#[derive(Clone, Debug)]
pub struct Stats {
