}

impl Stats {
    fn new(which: WhichStats) -> Stats {
        let (mut sum, mut minmax, mut online, mut mode, mut median) = (None, None, None, None, None);
        if which.sum {
            sum = Some(Default::default());
        }
        if which.range {
            minmax = Some(Default::default());
        }
        if which.dist {
            online = Some(Default::default());
        }
        if which.mode || which.cardinality {
            mode = Some(Unsorted::default());
        }
        if which.median {
            median = Some(Unsorted::default());
        }
        Stats { typ: FieldType::TNull, sum, minmax, online, mode, median, which }
    }

    fn add(&mut self, sample: &[u8]) {
        let sample_type = FieldType::from_sample(sample);
        self.typ = self.typ.merge(sample_type);

        let t = self.typ;
        if let Some(v) = self.sum.as_mut() {
            v.add(t, sample);
        }
        if let Some(v) = self.minmax.as_mut() {
            v.add(t, sample);
        }
        if let Some(v) = self.mode.as_mut() {
            v.add(sample.to_vec());
        }
        match self.typ {
            FieldType::TUnknown => {}
            FieldType::TNull => {
                if self.which.include_nulls {
                    if let Some(v) = self.online.as_mut() {
                        v.add_null();
                    }
                }
            }
            FieldType::TUnicode => {}
            FieldType::TFloat | FieldType::TInteger => {
                if sample_type.is_null() {
                    if self.which.include_nulls {
                        if let Some(v) = self.online.as_mut() {
                            v.add_null();
                        }
                    }
                } else {
                    let n = from_bytes::<f64>(sample).unwrap();
                    if let Some(v) = self.median.as_mut() {
                        v.add(n);
                    }
                    if let Some(v) = self.online.as_mut() {
                        v.add(n);
                    }
                }
            }
        }
    }

    fn merge(&mut self, other: Stats) {
        self.typ = self.typ.merge(other.typ);
        match (self.sum.as_mut(), other.sum) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.minmax.as_mut(), other.minmax) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.online.as_mut(), other.online) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.mode.as_mut(), other.mode) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.median.as_mut(), other.median) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
    }

    fn to_record(&self) -> Vec<String> {
        let typ = self.typ;
        let mut pieces = vec![];
        let empty = String::new;

        pieces.push(typ.to_string());
        match self.sum.as_ref().and_then(|sum| sum.show(typ)) {
            Some(sum) => pieces.push(sum),
            None => pieces.push(empty()),
        }
        match self.minmax.as_ref().and_then(|mm| mm.show(typ)) {
            Some(mm) => {
                pieces.push(mm.0);
                pieces.push(mm.1);
            }
            None => {
                pieces.push(empty());
                pieces.push(empty());
            }
        }
        match self.minmax.as_ref().and_then(|mm| mm.len_range()) {
            Some(mm) => {
                pieces.push(mm.0);
                pieces.push(mm.1);
            }
            None => {
                pieces.push(empty());
                pieces.push(empty());
            }
        }

        if !self.typ.is_number() {
            pieces.push(empty());
            pieces.push(empty());
        } else {
            match self.online {
                Some(ref v) => {
                    pieces.push(v.mean().to_string());
                    pieces.push(v.stddev().to_string());
                }
                None => {
                    pieces.push(empty());
                    pieces.push(empty());
                }
            }
        }
        match self.median.as_ref().and_then(|v| v.median()) {
            None => {
                if self.which.median {
                    pieces.push(empty());
                }
            }
            Some(v) => pieces.push(v.to_string()),
        }
        match self.mode.as_ref() {
            None => {
                if self.which.mode {
                    pieces.push(empty());
                }
                if self.which.cardinality {
                    pieces.push(empty());
                }
            }
            Some(ref v) => {
                if self.which.mode {
                    let lossy = |s: Vec<u8>| String::from_utf8_lossy(&s).into_owned();
                    pieces.push(v.mode().map_or("N/A".to_owned(), lossy));
                }
                if self.which.cardinality {
                    pieces.push(v.cardinality().to_string());
                }
            }
        }
        pieces
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FieldType {
    TUnknown,
    TNull,
    TUnicode,
    TFloat,
    TInteger,
}

impl FieldType {
    fn from_sample(sample: &[u8]) -> FieldType {
        if sample.is_empty() {
            return FieldType::TNull;
        }
        let string = match str::from_utf8(sample) {
            Err(_) => return FieldType::TUnknown,
            Ok(s) => s,
        };
        if string.parse::<i64>().is_ok() {
            return FieldType::TInteger;
        }
        if string.parse::<f64>().is_ok() {
            return FieldType::TFloat;
        }
        FieldType::TUnicode
    }

    fn merge(self, other: FieldType) -> FieldType {
        use self::FieldType::*;
        match (self, other) {
            (TUnicode, TUnicode) => TUnicode,
            (TFloat, TFloat) => TFloat,
            (TInteger, TInteger) => TInteger,
            // Null does not impact the type.
            (TNull, any) | (any, TNull) => any,
            // There's no way to get around an unknown.
            (TUnknown, _) | (_, TUnknown) => TUnknown,
            // Integers can degrade to floats.
            (TFloat, TInteger) | (TInteger, TFloat) => TFloat,
            // Numbers can degrade to Unicode strings.
            (TUnicode, TFloat) | (TFloat, TUnicode) => TUnicode,
            (TUnicode, TInteger) | (TInteger, TUnicode) => TUnicode,
        }
    }

    fn is_number(&self) -> bool {
        *self == FieldType::TFloat || *self == FieldType::TInteger
    }

    fn is_null(&self) -> bool {
        *self == FieldType::TNull
    }
}

impl fmt::Display for FieldType {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            FieldType::TUnknown => write!(f, "Unknown"),
            FieldType::TNull => write!(f, "NULL"),
            FieldType::TUnicode => write!(f, "Unicode"),
            FieldType::TFloat => write!(f, "Float"),
            FieldType::TInteger => write!(f, "Integer"),
        }
    }
}

/// A sum that can be either an integer or a float depending on the type.
#[derive(Clone, Debug, Default)]
struct TypedSum {
    integer: i64,
    float: Option<f64>,
}

impl TypedSum {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        if sample.is_empty() {
            return;
        }
        match typ {
            FieldType::TFloat => {
                let float: f64 = from_bytes::<f64>(sample).unwrap_or(0.0);
                match self.float {
                    None => {
                        self.float = Some((self.integer as f64) + float);
                    }
                    Some(ref mut f) => {
                        *f += float;
                    }
                }
            }
            FieldType::TInteger => {
                if let Some(ref mut float) = self.float {
                    *float += from_bytes::<f64>(sample).unwrap_or(0.0);
                } else {
                    self.integer = self.integer.wrapping_add(from_bytes::<i64>(sample).unwrap_or(0));
                }
            }
            _ => {}
        }
    }

    fn merge(&mut self, other: TypedSum) {
        match (self.float, other.float) {
            (Some(f1), Some(f2)) => self.float = Some(f1 + f2),
            (Some(f1), None) => self.float = Some(f1 + (other.integer as f64)),
            (None, Some(f2)) => self.float = Some((self.integer as f64) + f2),
            (None, None) => self.integer = self.integer.wrapping_add(other.integer),
        }
    }

    fn show(&self, typ: FieldType) -> Option<String> {
        match typ {
            FieldType::TNull | FieldType::TUnicode | FieldType::TUnknown => None,
            FieldType::TInteger => Some(self.integer.to_string()),
            FieldType::TFloat => Some(self.float.unwrap_or(0.0).to_string()),
        }
    }
}

#[derive(Clone, Debug, Default)]
struct TypedMinMax {
    strings: MinMax<Vec<u8>>,
    str_len: MinMax<usize>,
    integers: MinMax<i64>,
    floats: MinMax<f64>,
}

impl TypedMinMax {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        self.str_len.add(sample.len());
        if sample.is_empty() {
            return;
        }
        self.strings.add(sample.to_vec());
        match typ {
            FieldType::TUnicode | FieldType::TUnknown | FieldType::TNull => {}
            FieldType::TFloat => {
                let n = str::from_utf8(sample).ok().and_then(|s| s.parse::<f64>().ok()).unwrap_or(0.0);
                self.floats.add(n);
                self.integers.add(n as i64);
            }
            FieldType::TInteger => {
                let n = str::from_utf8(sample).ok().and_then(|s| s.parse::<i64>().ok()).unwrap_or(0);
                self.integers.add(n);
                self.floats.add(n as f64);
            }
        }
    }

    fn len_range(&self) -> Option<(String, String)> {
        match (self.str_len.min(), self.str_len.max()) {
            (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
            _ => None,
        }
    }

    fn show(&self, typ: FieldType) -> Option<(String, String)> {
        match typ {
            FieldType::TNull => None,
            FieldType::TUnicode | FieldType::TUnknown => match (self.strings.min(), self.strings.max()) {
                (Some(min), Some(max)) => {
                    let min = String::from_utf8_lossy(min).to_string();
                    let max = String::from_utf8_lossy(max).to_string();
                    Some((min, max))
                }
                _ => None,
            },
            FieldType::TInteger => match (self.integers.min(), self.integers.max()) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
            FieldType::TFloat => match (self.floats.min(), self.floats.max()) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
        }
    }

    fn merge(&mut self, other: TypedMinMax) {
        self.strings.merge(other.strings);
        self.str_len.merge(other.str_len);
        self.integers.merge(other.integers);
        self.floats.merge(other.floats);
    }
}

#[derive(Clone, Debug, Default)]
struct MinMax<T> {
    min: Option<T>,
    max: Option<T>,
}

impl<T: PartialOrd + Clone> MinMax<T> {
    fn add(&mut self, v: T) {
        match self.min {
            None => self.min = Some(v.clone()),
            Some(ref mut m) => {
                if v < *m {
                    *m = v.clone();
                }
            }
        }
        match self.max {
            None => self.max = Some(v),
            Some(ref mut m) => {
                if v > *m {
                    *m = v;
                }
            }
        }
    }

    fn min(&self) -> Option<&T> {
        self.min.as_ref()
    }

    fn max(&self) -> Option<&T> {
        self.max.as_ref()
    }

    fn merge(&mut self, other: MinMax<T>) {
        if let Some(v) = other.min {
            self.add_min(v);
        }
        if let Some(v) = other.max {
            self.add_max(v);
        }
    }

    fn add_min(&mut self, v: T) {
        match self.min {
            None => self.min = Some(v),
            Some(ref mut m) => {
                if v < *m {
                    *m = v;
                }
            }
        }
    }

    fn add_max(&mut self, v: T) {
        match self.max {
            None => self.max = Some(v),
            Some(ref mut m) => {
                if v > *m {
                    *m = v;
                }
            }
        }
    }
}

/// Online mean and variance (Welford's algorithm).
#[derive(Clone, Copy, Debug, Default)]
pub struct OnlineStats {
    size: u64,
    mean: f64,
    q: f64,
}

impl OnlineStats {
    pub fn add(&mut self, sample: f64) {
        let oldmean = self.mean;
        self.size += 1;
        self.mean += (sample - oldmean) / (self.size as f64);
        self.q += (sample - oldmean) * (sample - self.mean);
    }

    pub fn add_null(&mut self) {
        self.add(0.0);
    }

    pub fn mean(&self) -> f64 {
        self.mean
    }

    pub fn variance(&self) -> f64 {
        self.q / (self.size as f64)
    }

    pub fn stddev(&self) -> f64 {
        self.variance().sqrt()
    }

    pub fn merge(&mut self, v: OnlineStats) {
        if v.size == 0 {
            return;
        }
        if self.size == 0 {
            *self = v;
            return;
        }
        let (s1, s2) = (self.size as f64, v.size as f64);
        let meandiffsq = (self.mean - v.mean) * (self.mean - v.mean);
        let mean = ((s1 * self.mean) + (s2 * v.mean)) / (s1 + s2);
        let var = (((s1 * self.variance()) + (s2 * v.variance())) / (s1 + s2))
            + ((s1 * s2 * meandiffsq) / ((s1 + s2) * (s1 + s2)));
        self.size += v.size;
        self.mean = mean;
        self.q = var * (self.size as f64);
    }
}

/// A collection of unsorted values that can produce a median or mode.
#[derive(Clone, Debug)]
pub struct Unsorted<T> {
    data: Vec<T>,
}

impl<T> Default for Unsorted<T> {
    fn default() -> Unsorted<T> {
        Unsorted { data: vec![] }
    }
}

impl<T: Clone> Unsorted<T> {
    pub fn add(&mut self, v: T) {
        self.data.push(v);
    }

    pub fn merge(&mut self, other: Unsorted<T>) {
        self.data.extend(other.data);
    }
}

impl<T: PartialOrd + Clone + Eq> Unsorted<T> {
    pub fn mode(&self) -> Option<T> {
        if self.data.is_empty() {
            return None;
        }
        let mut sorted = self.data.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let mut mode: Option<T> = None;
        let mut mode_count: usize = 0;
        let mut tie = false;
        let mut i = 0;
        while i < sorted.len() {
            let mut j = i + 1;
            while j < sorted.len() && sorted[j] == sorted[i] {
                j += 1;
            }
            let count = j - i;
            if count > mode_count {
                mode = Some(sorted[i].clone());
                mode_count = count;
                tie = false;
            } else if count == mode_count {
                tie = true;
            }
            i = j;
        }
        if tie || mode_count < 2 {
            None
        } else {
            mode
        }
    }

    pub fn cardinality(&self) -> usize {
        let mut sorted = self.data.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let mut n = 0;
        let mut i = 0;
        while i < sorted.len() {
            let mut j = i + 1;
            while j < sorted.len() && sorted[j] == sorted[i] {
                j += 1;
            }
            n += 1;
            i = j;
        }
        n
    }
}

impl Unsorted<f64> {
    pub fn median(&self) -> Option<f64> {
        if self.data.is_empty() {
            return None;
        }
        let mut sorted = self.data.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let n = sorted.len();
        if n % 2 == 0 {
            Some((sorted[n / 2 - 1] + sorted[n / 2]) / 2.0)
        } else {
            Some(sorted[n / 2])
        }
    }
}

fn from_bytes<T: str::FromStr>(bytes: &[u8]) -> Option<T> {
    str::from_utf8(bytes).ok().and_then(|s| s.parse().ok())
}

