use std::borrow::ToOwned;
use std::cmp::Ordering;
use std::default::Default;
use std::fmt;
use std::fs;
use std::io;
use std::iter::repeat;
use std::str;
use std::thread;

use crate::config::{Config, Delimiter};
use crate::csv::ByteRecord;
use crate::index::Indexed;
use crate::select::{SelectColumns, Selection};
use crate::util;
use crate::CliResult;

static USAGE: &str = "
Computes basic statistics on CSV data.

Basic statistics includes mean, median, mode, standard deviation, sum, max and
min values. Note that some statistics are expensive to compute, so they must
be enabled explicitly. By default, the following statistics are reported for
*every* column in the CSV data: mean, max, min and standard deviation. The
default set of statistics corresponds to statistics that can be computed
efficiently on a stream of data (i.e., constant memory).

Computing statistics on a large file can be made much faster if you create
an index for it first with 'xsv index'.

Usage:
    xsv stats [options] [<input>]

stats options:
    -s, --select <arg>     Select a subset of columns to compute stats for.
                           See 'xsv select --help' for the format details.
                           This is provided here because piping 'xsv select'
                           into 'xsv stats' will disable the use of indexing.
    --everything           Show all statistics available.
    --mode                 Show the mode.
                           This requires storing all CSV data in memory.
    --cardinality          Show the cardinality.
                           This requires storing all CSV data in memory.
    --median               Show the median.
                           This requires storing all CSV data in memory.
    --nulls                Include NULLs in the population size for computing
                           mean and standard deviation.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. i.e., They will be included
                           in statistics.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Clone)]
struct Args {
    arg_input: Option<String>,
    flag_select: SelectColumns,
    flag_everything: bool,
    flag_mode: bool,
    flag_cardinality: bool,
    flag_median: bool,
    flag_nulls: bool,
    flag_jobs: usize,
    flag_output: Option<String>,
    flag_no_headers: bool,
    flag_delimiter: Option<Delimiter>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = util::get_args(USAGE, argv)?;
    let args = Args {
        arg_input: a.get_opt_str("<input>"),
        flag_select: match a.get_opt_str("--select") {
            None => SelectColumns::parse("")?,
            Some(s) => SelectColumns::parse(&s)?,
        },
        flag_everything: a.get_bool("--everything"),
        flag_mode: a.get_bool("--mode"),
        flag_cardinality: a.get_bool("--cardinality"),
        flag_median: a.get_bool("--median"),
        flag_nulls: a.get_bool("--nulls"),
        flag_jobs: a.get_usize("--jobs")?,
        flag_output: a.get_opt_str("--output"),
        flag_no_headers: a.get_bool("--no-headers"),
        flag_delimiter: util::delimiter(&a)?,
    };

    let mut wtr = Config::new(&args.flag_output).writer()?;
    let (headers, stats) = match args.rconfig().indexed()? {
        None => args.sequential_stats(),
        Some(idx) => {
            if args.njobs() == 1 {
                args.sequential_stats()
            } else {
                args.parallel_stats(idx)
            }
        }
    }?;
    let stats = args.stats_to_records(stats);

    wtr.write_record(&args.stat_headers())?;
    let fields = headers.iter().zip(stats.into_iter());
    for (i, (header, stat)) in fields.enumerate() {
        let header = if args.flag_no_headers {
            i.to_string().into_bytes()
        } else {
            header.to_vec()
        };
        let stat = stat.iter().map(|f| f.as_bytes());
        wtr.write_record(vec![&*header].into_iter().chain(stat))?;
    }
    wtr.flush()?;
    Ok(())
}

impl Args {
    fn sequential_stats(&self) -> CliResult<(ByteRecord, Vec<Stats>)> {
        let mut rdr = self.rconfig().reader()?;
        let (headers, sel) = self.sel_headers(&mut rdr)?;
        let stats = self.compute(&sel, rdr.byte_records())?;
        Ok((headers, stats))
    }

    fn parallel_stats(
        &self,
        mut idx: Indexed<fs::File, fs::File>,
    ) -> CliResult<(ByteRecord, Vec<Stats>)> {
        // N.B. This is probably more complicated than it needs to be.
        if idx.count() == 0 {
            return self.sequential_stats();
        }

        let (headers, sel) = self.sel_headers(&mut *idx)?;

        let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
        let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);

        let mut handles = vec![];
        for i in 0..nchunks {
            let (args, sel) = (self.clone(), sel.clone());
            handles.push(thread::spawn(move || -> CliResult<Vec<Stats>> {
                let mut idx = args.rconfig().indexed()?.unwrap();
                idx.seek((i * chunk_size) as u64)?;
                let it = idx.byte_records().take(chunk_size);
                args.compute(&sel, it)
            }));
        }
        let mut merged: Option<Vec<Stats>> = None;
        for h in handles {
            let stats = h.join().expect("thread panicked")?;
            merged = Some(match merged {
                None => stats,
                Some(mut acc) => {
                    for (a, b) in acc.iter_mut().zip(stats.into_iter()) {
                        a.merge(b);
                    }
                    acc
                }
            });
        }
        Ok((headers, merged.unwrap_or_default()))
    }

    fn stats_to_records(&self, stats: Vec<Stats>) -> Vec<Vec<String>> {
        stats.into_iter().map(|s| s.to_record()).collect()
    }

    fn compute<I>(&self, sel: &Selection, it: I) -> CliResult<Vec<Stats>>
    where
        I: Iterator<Item = crate::csv::Result<ByteRecord>>,
    {
        let mut stats = self.new_stats(sel.len());
        for row in it {
            let row = row?;
            for (i, field) in sel.select(&row).enumerate() {
                stats[i].add(field);
            }
        }
        Ok(stats)
    }

    fn sel_headers<R: io::Read>(
        &self,
        rdr: &mut crate::csv::Reader<R>,
    ) -> CliResult<(ByteRecord, Selection)> {
        let headers = rdr.byte_headers()?.clone();
        let sel = self.rconfig().selection(&headers)?;
        Ok((ByteRecord::from_fields(sel.select(&headers)), sel))
    }

    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.flag_select.clone())
    }

    fn njobs(&self) -> usize {
        util::njobs(self.flag_jobs)
    }

    fn new_stats(&self, record_len: usize) -> Vec<Stats> {
        repeat(Stats::new(WhichStats {
            include_nulls: self.flag_nulls,
            sum: true,
            range: true,
            dist: true,
            cardinality: self.flag_cardinality || self.flag_everything,
            median: self.flag_median || self.flag_everything,
            mode: self.flag_mode || self.flag_everything,
        }))
        .take(record_len)
        .collect()
    }

    fn stat_headers(&self) -> ByteRecord {
        let mut fields = vec![
            "field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev",
        ];
        let all = self.flag_everything;
        if self.flag_median || all {
            fields.push("median");
        }
        if self.flag_mode || all {
            fields.push("mode");
        }
        if self.flag_cardinality || all {
            fields.push("cardinality");
        }
        ByteRecord::from_fields(fields)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct WhichStats {
    include_nulls: bool,
    sum: bool,
    range: bool,
    dist: bool,
    cardinality: bool,
    median: bool,
    mode: bool,
}

#[derive(Clone, Debug)]
pub struct Stats {
    typ: FieldType,
    sum: Option<TypedSum>,
    minmax: Option<TypedMinMax>,
    online: Option<OnlineStats>,
    mode: Option<Unsorted<Vec<u8>>>,
    median: Option<Unsorted<f64>>,
    which: WhichStats,
}

impl Stats {
    fn new(which: WhichStats) -> Stats {
        let (mut sum, mut minmax, mut online, mut mode, mut median) = (None, None, None, None, None);
        if which.sum {
            sum = Some(Default::default());
        }
        if which.range {
            minmax = Some(Default::default());
        }
        if which.dist {
            online = Some(Default::default());
        }
        if which.mode || which.cardinality {
            mode = Some(Unsorted::default());
        }
        if which.median {
            median = Some(Unsorted::default());
        }
        Stats { typ: FieldType::TNull, sum, minmax, online, mode, median, which }
    }

    fn add(&mut self, sample: &[u8]) {
        let sample_type = FieldType::from_sample(sample);
        self.typ = self.typ.merge(sample_type);

        let t = self.typ;
        if let Some(v) = self.sum.as_mut() {
            v.add(t, sample);
        }
        if let Some(v) = self.minmax.as_mut() {
            v.add(t, sample);
        }
        if let Some(v) = self.mode.as_mut() {
            v.add(sample.to_vec());
        }
        match self.typ {
            FieldType::TUnknown => {}
            FieldType::TNull => {
                if self.which.include_nulls {
                    if let Some(v) = self.online.as_mut() {
                        v.add_null();
                    }
                }
            }
            FieldType::TUnicode => {}
            FieldType::TFloat | FieldType::TInteger => {
                if sample_type.is_null() {
                    if self.which.include_nulls {
                        if let Some(v) = self.online.as_mut() {
                            v.add_null();
                        }
                    }
                } else {
                    let n = from_bytes::<f64>(sample).unwrap();
                    if let Some(v) = self.median.as_mut() {
                        v.add(n);
                    }
                    if let Some(v) = self.online.as_mut() {
                        v.add(n);
                    }
                }
            }
        }
    }

    fn merge(&mut self, other: Stats) {
        self.typ = self.typ.merge(other.typ);
        match (self.sum.as_mut(), other.sum) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.minmax.as_mut(), other.minmax) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.online.as_mut(), other.online) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.mode.as_mut(), other.mode) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
        match (self.median.as_mut(), other.median) {
            (Some(a), Some(b)) => a.merge(b),
            _ => {}
        }
    }

    fn to_record(&self) -> Vec<String> {
        let typ = self.typ;
        let mut pieces = vec![];
        let empty = String::new;

        pieces.push(typ.to_string());
        match self.sum.as_ref().and_then(|sum| sum.show(typ)) {
            Some(sum) => pieces.push(sum),
            None => pieces.push(empty()),
        }
        match self.minmax.as_ref().and_then(|mm| mm.show(typ)) {
            Some(mm) => {
                pieces.push(mm.0);
                pieces.push(mm.1);
            }
            None => {
                pieces.push(empty());
                pieces.push(empty());
            }
        }
        match self.minmax.as_ref().and_then(|mm| mm.len_range()) {
            Some(mm) => {
                pieces.push(mm.0);
                pieces.push(mm.1);
            }
            None => {
                pieces.push(empty());
                pieces.push(empty());
            }
        }

        if !self.typ.is_number() {
            pieces.push(empty());
            pieces.push(empty());
        } else {
            match self.online {
                Some(ref v) => {
                    pieces.push(v.mean().to_string());
                    pieces.push(v.stddev().to_string());
                }
                None => {
                    pieces.push(empty());
                    pieces.push(empty());
                }
            }
        }
        match self.median.as_ref().and_then(|v| v.median()) {
            None => {
                if self.which.median {
                    pieces.push(empty());
                }
            }
            Some(v) => pieces.push(v.to_string()),
        }
        match self.mode.as_ref() {
            None => {
                if self.which.mode {
                    pieces.push(empty());
                }
                if self.which.cardinality {
                    pieces.push(empty());
                }
            }
            Some(ref v) => {
                if self.which.mode {
                    let lossy = |s: Vec<u8>| String::from_utf8_lossy(&s).into_owned();
                    pieces.push(v.mode().map_or("N/A".to_owned(), lossy));
                }
                if self.which.cardinality {
                    pieces.push(v.cardinality().to_string());
                }
            }
        }
        pieces
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FieldType {
    TUnknown,
    TNull,
    TUnicode,
    TFloat,
    TInteger,
}

impl FieldType {
    fn from_sample(sample: &[u8]) -> FieldType {
        if sample.is_empty() {
            return FieldType::TNull;
        }
        let string = match str::from_utf8(sample) {
            Err(_) => return FieldType::TUnknown,
            Ok(s) => s,
        };
        if string.parse::<i64>().is_ok() {
            return FieldType::TInteger;
        }
        if string.parse::<f64>().is_ok() {
            return FieldType::TFloat;
        }
        FieldType::TUnicode
    }

    fn merge(self, other: FieldType) -> FieldType {
        use self::FieldType::*;
        match (self, other) {
            (TUnicode, TUnicode) => TUnicode,
            (TFloat, TFloat) => TFloat,
            (TInteger, TInteger) => TInteger,
            // Null does not impact the type.
            (TNull, any) | (any, TNull) => any,
            // There's no way to get around an unknown.
            (TUnknown, _) | (_, TUnknown) => TUnknown,
            // Integers can degrade to floats.
            (TFloat, TInteger) | (TInteger, TFloat) => TFloat,
            // Numbers can degrade to Unicode strings.
            (TUnicode, TFloat) | (TFloat, TUnicode) => TUnicode,
            (TUnicode, TInteger) | (TInteger, TUnicode) => TUnicode,
        }
    }

    fn is_number(&self) -> bool {
        *self == FieldType::TFloat || *self == FieldType::TInteger
    }

    fn is_null(&self) -> bool {
        *self == FieldType::TNull
    }
}

impl fmt::Display for FieldType {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            FieldType::TUnknown => write!(f, "Unknown"),
            FieldType::TNull => write!(f, "NULL"),
            FieldType::TUnicode => write!(f, "Unicode"),
            FieldType::TFloat => write!(f, "Float"),
            FieldType::TInteger => write!(f, "Integer"),
        }
    }
}

/// A sum that can be either an integer or a float depending on the type.
#[derive(Clone, Debug, Default)]
struct TypedSum {
    integer: i64,
    float: Option<f64>,
}

impl TypedSum {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        if sample.is_empty() {
            return;
        }
        match typ {
            FieldType::TFloat => {
                let float: f64 = from_bytes::<f64>(sample).unwrap_or(0.0);
                match self.float {
                    None => {
                        self.float = Some((self.integer as f64) + float);
                    }
                    Some(ref mut f) => {
                        *f += float;
                    }
                }
            }
            FieldType::TInteger => {
                if let Some(ref mut float) = self.float {
                    *float += from_bytes::<f64>(sample).unwrap_or(0.0);
                } else {
                    self.integer = self.integer.wrapping_add(from_bytes::<i64>(sample).unwrap_or(0));
                }
            }
            _ => {}
        }
    }

    fn merge(&mut self, other: TypedSum) {
        match (self.float, other.float) {
            (Some(f1), Some(f2)) => self.float = Some(f1 + f2),
            (Some(f1), None) => self.float = Some(f1 + (other.integer as f64)),
            (None, Some(f2)) => self.float = Some((self.integer as f64) + f2),
            (None, None) => self.integer = self.integer.wrapping_add(other.integer),
        }
    }

    fn show(&self, typ: FieldType) -> Option<String> {
        match typ {
            FieldType::TNull | FieldType::TUnicode | FieldType::TUnknown => None,
            FieldType::TInteger => Some(self.integer.to_string()),
            FieldType::TFloat => Some(self.float.unwrap_or(0.0).to_string()),
        }
    }
}

#[derive(Clone, Debug, Default)]
struct TypedMinMax {
    strings: MinMax<Vec<u8>>,
    str_len: MinMax<usize>,
    integers: MinMax<i64>,
    floats: MinMax<f64>,
}

impl TypedMinMax {
    fn add(&mut self, typ: FieldType, sample: &[u8]) {
        self.str_len.add(sample.len());
        if sample.is_empty() {
            return;
        }
        self.strings.add(sample.to_vec());
        match typ {
            FieldType::TUnicode | FieldType::TUnknown | FieldType::TNull => {}
            FieldType::TFloat => {
                let n = str::from_utf8(sample).ok().and_then(|s| s.parse::<f64>().ok()).unwrap_or(0.0);
                self.floats.add(n);
                self.integers.add(n as i64);
            }
            FieldType::TInteger => {
                let n = str::from_utf8(sample).ok().and_then(|s| s.parse::<i64>().ok()).unwrap_or(0);
                self.integers.add(n);
                self.floats.add(n as f64);
            }
        }
    }

    fn len_range(&self) -> Option<(String, String)> {
        match (self.str_len.min(), self.str_len.max()) {
            (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
            _ => None,
        }
    }

    fn show(&self, typ: FieldType) -> Option<(String, String)> {
        match typ {
            FieldType::TNull => None,
            FieldType::TUnicode | FieldType::TUnknown => match (self.strings.min(), self.strings.max()) {
                (Some(min), Some(max)) => {
                    let min = String::from_utf8_lossy(min).to_string();
                    let max = String::from_utf8_lossy(max).to_string();
                    Some((min, max))
                }
                _ => None,
            },
            FieldType::TInteger => match (self.integers.min(), self.integers.max()) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
            FieldType::TFloat => match (self.floats.min(), self.floats.max()) {
                (Some(min), Some(max)) => Some((min.to_string(), max.to_string())),
                _ => None,
            },
        }
    }

    fn merge(&mut self, other: TypedMinMax) {
        self.strings.merge(other.strings);
        self.str_len.merge(other.str_len);
        self.integers.merge(other.integers);
        self.floats.merge(other.floats);
    }
}

#[derive(Clone, Debug, Default)]
struct MinMax<T> {
    min: Option<T>,
    max: Option<T>,
}

impl<T: PartialOrd + Clone> MinMax<T> {
    fn add(&mut self, v: T) {
        match self.min {
            None => self.min = Some(v.clone()),
            Some(ref mut m) => {
                if v < *m {
                    *m = v.clone();
                }
            }
        }
        match self.max {
            None => self.max = Some(v),
            Some(ref mut m) => {
                if v > *m {
                    *m = v;
                }
            }
        }
    }

    fn min(&self) -> Option<&T> {
        self.min.as_ref()
    }

    fn max(&self) -> Option<&T> {
        self.max.as_ref()
    }

    fn merge(&mut self, other: MinMax<T>) {
        if let Some(v) = other.min {
            self.add_min(v);
        }
        if let Some(v) = other.max {
            self.add_max(v);
        }
    }

    fn add_min(&mut self, v: T) {
        match self.min {
            None => self.min = Some(v),
            Some(ref mut m) => {
                if v < *m {
                    *m = v;
                }
            }
        }
    }

    fn add_max(&mut self, v: T) {
        match self.max {
            None => self.max = Some(v),
            Some(ref mut m) => {
                if v > *m {
                    *m = v;
                }
            }
        }
    }
}

/// Online mean and variance (Welford's algorithm).
#[derive(Clone, Copy, Debug, Default)]
pub struct OnlineStats {
    size: u64,
    mean: f64,
    q: f64,
}

impl OnlineStats {
    pub fn add(&mut self, sample: f64) {
        let oldmean = self.mean;
        self.size += 1;
        self.mean += (sample - oldmean) / (self.size as f64);
        self.q += (sample - oldmean) * (sample - self.mean);
    }

    pub fn add_null(&mut self) {
        self.add(0.0);
    }

    pub fn mean(&self) -> f64 {
        self.mean
    }

    pub fn variance(&self) -> f64 {
        self.q / (self.size as f64)
    }

    pub fn stddev(&self) -> f64 {
        self.variance().sqrt()
    }

    pub fn merge(&mut self, v: OnlineStats) {
        if v.size == 0 {
            return;
        }
        if self.size == 0 {
            *self = v;
            return;
        }
        let (s1, s2) = (self.size as f64, v.size as f64);
        let meandiffsq = (self.mean - v.mean) * (self.mean - v.mean);
        let mean = ((s1 * self.mean) + (s2 * v.mean)) / (s1 + s2);
        let var = (((s1 * self.variance()) + (s2 * v.variance())) / (s1 + s2))
            + ((s1 * s2 * meandiffsq) / ((s1 + s2) * (s1 + s2)));
        self.size += v.size;
        self.mean = mean;
        self.q = var * (self.size as f64);
    }
}

/// A collection of unsorted values that can produce a median or mode.
#[derive(Clone, Debug)]
pub struct Unsorted<T> {
    data: Vec<T>,
}

impl<T> Default for Unsorted<T> {
    fn default() -> Unsorted<T> {
        Unsorted { data: vec![] }
    }
}

impl<T: Clone> Unsorted<T> {
    pub fn add(&mut self, v: T) {
        self.data.push(v);
    }

    pub fn merge(&mut self, other: Unsorted<T>) {
        self.data.extend(other.data);
    }
}

impl<T: PartialOrd + Clone + Eq> Unsorted<T> {
    pub fn mode(&self) -> Option<T> {
        if self.data.is_empty() {
            return None;
        }
        let mut sorted = self.data.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let mut mode: Option<T> = None;
        let mut mode_count: usize = 0;
        let mut tie = false;
        let mut i = 0;
        while i < sorted.len() {
            let mut j = i + 1;
            while j < sorted.len() && sorted[j] == sorted[i] {
                j += 1;
            }
            let count = j - i;
            if count > mode_count {
                mode = Some(sorted[i].clone());
                mode_count = count;
                tie = false;
            } else if count == mode_count {
                tie = true;
            }
            i = j;
        }
        if tie || mode_count < 2 {
            None
        } else {
            mode
        }
    }

    pub fn cardinality(&self) -> usize {
        let mut sorted = self.data.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let mut n = 0;
        let mut i = 0;
        while i < sorted.len() {
            let mut j = i + 1;
            while j < sorted.len() && sorted[j] == sorted[i] {
                j += 1;
            }
            n += 1;
            i = j;
        }
        n
    }
}

impl Unsorted<f64> {
    pub fn median(&self) -> Option<f64> {
        if self.data.is_empty() {
            return None;
        }
        let mut sorted = self.data.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(Ordering::Equal));
        let n = sorted.len();
        if n % 2 == 0 {
            Some((sorted[n / 2 - 1] + sorted[n / 2]) / 2.0)
        } else {
            Some(sorted[n / 2])
        }
    }
}

