use std::num::Wrapping as w;

const RAND_SIZE_64_LEN: usize = 8;
const RAND_SIZE_64: usize = 1 << RAND_SIZE_64_LEN;

struct Isaac64 {
    cnt: usize,
    rsl: [w<u64>; RAND_SIZE_64],
    mem: [w<u64>; RAND_SIZE_64],
    a: w<u64>,
    b: w<u64>,
    c: w<u64>,
