impl Isaac64 {
    fn from_seed(seed: &[u64]) -> Isaac64 {
        let mut rng = Isaac64 {
            cnt: 0,
            rsl: [w(0); RAND_SIZE_64],
            mem: [w(0); RAND_SIZE_64],
            a: w(0), b: w(0), c: w(0),
        };
        for (r, s) in rng.rsl.iter_mut().zip(seed.iter().chain(std::iter::repeat(&0))) {
            *r = w(*s);
        }
        rng.init(true);
        rng
    }

    fn init(&mut self, use_rsl: bool) {
        let mut a = w(0x9e3779b97f4a7c13u64);
        let mut b = a; let mut c = a; let mut d = a; let mut e = a; let mut f = a; let mut g = a; let mut h = a;
        macro_rules! mix { () => {{
            a=a-e; f=f^(h>>9);  h=h+a;
            b=b-f; g=g^(a<<9);  a=a+b;
            c=c-g; h=h^(b>>23); b=b+c;
            d=d-h; a=a^(c<<15); c=c+d;
            e=e-a; b=b^(d>>14); d=d+e;
            f=f-b; c=c^(e<<20); e=e+f;
            g=g-c; d=d^(f>>17); f=f+g;
            h=h-d; e=e^(g<<14); g=g+h;
        }} }
        for _ in 0..4 { mix!(); }
        if use_rsl {
            macro_rules! memloop { ($arr:expr) => {{
                for i in (0..RAND_SIZE_64 / 8).map(|i| i * 8) {
                    a=a+$arr[i  ]; b=b+$arr[i+1]; c=c+$arr[i+2]; d=d+$arr[i+3];
                    e=e+$arr[i+4]; f=f+$arr[i+5]; g=g+$arr[i+6]; h=h+$arr[i+7];
                    mix!();
                    self.mem[i  ]=a; self.mem[i+1]=b; self.mem[i+2]=c; self.mem[i+3]=d;
                    self.mem[i+4]=e; self.mem[i+5]=f; self.mem[i+6]=g; self.mem[i+7]=h;
                }
            }} }
            let rsl = self.rsl;
            memloop!(rsl);
            let mem = self.mem;
            memloop!(mem);
