            w[i] = f2(w[i-2]).wrapping_add(w[i-7]).wrapping_add(f1(w[i-15])).wrapping_add(w[i-16]).wrapping_add(i as u32);
        }
        let mut p = [0u32; 512];
        let mut q = [0u32; 512];
        p.copy_from_slice(&w[256..768]);
        q.copy_from_slice(&w[768..1280]);
        let mut rng = Hc128 { p, q, counter: 0, buf: vec![], idx: 0 };
        // run 1024 steps discarding output
        for _ in 0..1024 { rng.step(); }
        rng.counter = 0;
        rng
    }

    fn h1(&self, x: u32) -> u32 {
        self.q[(x & 0xff) as usize].wrapping_add(self.q[256 + ((x >> 16) & 0xff) as usize])
    }
    fn h2(&self, x: u32) -> u32 {
        self.p[(x & 0xff) as usize].wrapping_add(self.p[256 + ((x >> 16) & 0xff) as usize])
    }

    fn step(&mut self) -> u32 {
        let i = self.counter;
        let j = i & 0x1ff;
        let out;
        if i < 512 {
            let (a, b, c) = (self.p[(j.wrapping_sub(3)) & 0x1ff], self.p[(j.wrapping_sub(10)) & 0x1ff], self.p[(j.wrapping_sub(511)) & 0x1ff]);
            self.p[j] = self.p[j].wrapping_add(g1(a, b, c));
            out = self.h1(self.p[(j.wrapping_sub(12)) & 0x1ff]) ^ self.p[j];
        } else {
            let (a, b, c) = (self.q[(j.wrapping_sub(3)) & 0x1ff], self.q[(j.wrapping_sub(10)) & 0x1ff], self.q[(j.wrapping_sub(511)) & 0x1ff]);
            self.q[j] = self.q[j].wrapping_add(g2(a, b, c));
            out = self.h2(self.q[(j.wrapping_sub(12)) & 0x1ff]) ^ self.q[j];
        }
        self.counter = (i + 1) & 0x3ff;
        out
    }

    pub fn next_u32(&mut self) -> u32 {
        if self.idx >= self.buf.len() {
            let mut b = vec![];
            for _ in 0..16 { b.push(self.step()); }
            self.buf = b;
            self.idx = 0;
        }
        let v = self.buf[self.idx];
        self.idx += 1;
        v
    }

    pub fn next_u64(&mut self) -> u64 {
        let lo = self.next_u32() as u64;
        let hi = self.next_u32() as u64;
        (hi << 32) | lo
    }
}
