//! A small deterministic random number generator (HC-128 stream cipher) with
//! uniform integer sampling.

use std::fs::File;
use std::io::Read;
use std::time::{SystemTime, UNIX_EPOCH};

pub struct Rng {
    p: [u32; 512],
    q: [u32; 512],
    counter: usize,
    buf: [u32; 16],
    idx: usize,
}

fn f1(x: u32) -> u32 {
    x.rotate_right(7) ^ x.rotate_right(18) ^ (x >> 3)
}
fn f2(x: u32) -> u32 {
    x.rotate_right(17) ^ x.rotate_right(19) ^ (x >> 10)
}
fn g1(x: u32, y: u32, z: u32) -> u32 {
    (x.rotate_right(10) ^ z.rotate_right(23)).wrapping_add(y.rotate_right(8))
}
fn g2(x: u32, y: u32, z: u32) -> u32 {
    (x.rotate_left(10) ^ z.rotate_left(23)).wrapping_add(y.rotate_left(8))
}

impl Rng {
    /// Creates a generator from a 32 byte seed (16 byte key, 16 byte iv).
    pub fn from_seed(seed: [u8; 32]) -> Rng {
        let mut key = [0u32; 4];
        let mut iv = [0u32; 4];
        for i in 0..4 {
            key[i] = u32::from_le_bytes([seed[4 * i], seed[4 * i + 1], seed[4 * i + 2], seed[4 * i + 3]]);
            iv[i] = u32::from_le_bytes([
                seed[16 + 4 * i],
                seed[16 + 4 * i + 1],
                seed[16 + 4 * i + 2],
                seed[16 + 4 * i + 3],
            ]);
        }
        let mut w = vec![0u32; 1280];
        for i in 0..4 {
            w[i] = key[i];
            w[i + 4] = key[i];
            w[i + 8] = iv[i];
            w[i + 12] = iv[i];
        }
        for i in 16..1280 {
            w[i] = f2(w[i - 2])
                .wrapping_add(w[i - 7])
                .wrapping_add(f1(w[i - 15]))
                .wrapping_add(w[i - 16])
                .wrapping_add(i as u32);
        }
        let mut p = [0u32; 512];
        let mut q = [0u32; 512];
        p.copy_from_slice(&w[256..768]);
        q.copy_from_slice(&w[768..1280]);
