                rng.p[j.wrapping_sub(10) & 0x1ff],
                rng.p[j.wrapping_sub(511) & 0x1ff],
            );
            let v = rng.p[j].wrapping_add(g1(a, b, c));
            rng.p[j] = v ^ rng.h1(rng.p[j.wrapping_sub(12) & 0x1ff]);
        }
        for j in 0..512usize {
            let (a, b, c) = (
                rng.q[j.wrapping_sub(3) & 0x1ff],
                rng.q[j.wrapping_sub(10) & 0x1ff],
                rng.q[j.wrapping_sub(511) & 0x1ff],
