            rng.q[j] = v ^ rng.h2(rng.q[j.wrapping_sub(12) & 0x1ff]);
        }
        rng.counter = 0;
        rng
    }

    /// Seeds from a single integer (written little-endian into the seed).
    pub fn from_u64(seed: u64) -> Rng {
        let mut buf = [0u8; 32];
        buf[..8].copy_from_slice(&seed.to_le_bytes());
        Rng::from_seed(buf)
    }

    /// Seeds from operating system entropy (falling back to the clock).
    pub fn from_entropy() -> Rng {
        let mut buf = [0u8; 32];
        let ok = File::open("/dev/urandom").and_then(|mut f| f.read_exact(&mut buf)).is_ok();
        if !ok {
            let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
            let a = now.as_nanos() as u64;
            let b = std::process::id() as u64;
            buf[..8].copy_from_slice(&a.to_le_bytes());
            buf[8..16].copy_from_slice(&b.to_le_bytes());
            buf[16..24].copy_from_slice(&(a ^ 0x9e3779b97f4a7c15).to_le_bytes());
        }
        Rng::from_seed(buf)
    }

    fn h1(&self, x: u32) -> u32 {
        self.q[(x & 0xff) as usize].wrapping_add(self.q[256 + ((x >> 16) & 0xff) as usize])
    }

    fn h2(&self, x: u32) -> u32 {
        self.p[(x & 0xff) as usize].wrapping_add(self.p[256 + ((x >> 16) & 0xff) as usize])
    }

    fn step(&mut self) -> u32 {
        let i = self.counter;
        let j = i & 0x1ff;
        let out;
        if i < 512 {
            let (a, b, c) = (
                self.p[j.wrapping_sub(3) & 0x1ff],
                self.p[j.wrapping_sub(10) & 0x1ff],
                self.p[j.wrapping_sub(511) & 0x1ff],
            );
            self.p[j] = self.p[j].wrapping_add(g1(a, b, c));
            out = self.h1(self.p[j.wrapping_sub(12) & 0x1ff]) ^ self.p[j];
        } else {
            let (a, b, c) = (
                self.q[j.wrapping_sub(3) & 0x1ff],
                self.q[j.wrapping_sub(10) & 0x1ff],
                self.q[j.wrapping_sub(511) & 0x1ff],
            );
            self.q[j] = self.q[j].wrapping_add(g2(a, b, c));
            out = self.h2(self.q[j.wrapping_sub(12) & 0x1ff]) ^ self.q[j];
        }
        self.counter = (i + 1) & 0x3ff;
        out
    }

    pub fn next_u32(&mut self) -> u32 {
        if self.idx >= 16 {
            for i in 0..16 {
                self.buf[i] = self.step();
            }
            self.idx = 0;
        }
        let v = self.buf[self.idx];
        self.idx += 1;
        v
    }

    pub fn next_u64(&mut self) -> u64 {
        let lo = self.next_u32() as u64;
        let hi = self.next_u32() as u64;
        (hi << 32) | lo
    }

