    pub fn shuffle<T>(&mut self, values: &mut [T]) {
        let mut i = values.len();
        while i >= 2 {
            i -= 1;
            let j = self.gen_range(0, (i + 1) as u64) as usize;
            values.swap(i, j);
        }
    }
