            rdr2,
            sel2,
            no_headers: rconf1.no_headers,
            casei: self.flag_no_case,
            nulls: self.flag_nulls,
        })
    }

    fn get_selections<R: std::io::Read>(
        &self,
        rconf1: &Config,
        rdr1: &mut Reader<R>,
        rconf2: &Config,
        rdr2: &mut Reader<R>,
    ) -> CliResult<(Selection, Selection)> {
