    values: HashMap<Vec<Vec<u8>>, Vec<usize>>,
    rows: Vec<ByteRecord>,
}

impl ValueIndex {
    fn new<R: std::io::Read>(
        rdr: &mut Reader<R>,
        sel: &Selection,
        casei: bool,
        nulls: bool,
    ) -> CliResult<ValueIndex> {
        let mut val_idx = HashMap::with_capacity(10000);
        let mut rows = vec![];
        let mut rowi = 0usize;
        // Make sure headers are parsed; with no headers the first row is
        // yielded as a regular record.
        rdr.byte_headers()?;
        let mut row = ByteRecord::new();
        while rdr.read_byte_record(&mut row)? {
            let fields: Vec<_> = sel.select(&row).map(|v| transform(v, casei)).collect();
            if nulls || !fields.iter().any(|f| f.is_empty()) {
                match val_idx.entry(fields) {
                    Entry::Vacant(v) => {
                        let mut rs = Vec::with_capacity(4);
                        rs.push(rowi);
                        v.insert(rs);
                    }
                    Entry::Occupied(mut v) => {
                        v.get_mut().push(rowi);
                    }
                }
            }
            rows.push(row.clone());
            rowi += 1;
        }
        Ok(ValueIndex { values: val_idx, rows })
    }
}

fn get_row_key(sel: &Selection, row: &ByteRecord, casei: bool) -> Vec<Vec<u8>> {
    sel.select(row).map(|v| transform(v, casei)).collect()
}

fn transform(bs: &[u8], casei: bool) -> Vec<u8> {
    match str::from_utf8(bs) {
        Err(_) => bs.to_vec(),
        Ok(s) => {
            if !casei {
                s.trim().as_bytes().to_vec()
            } else {
                let norm: String = s.trim().chars().map(|c| c.to_lowercase().next().unwrap()).collect();
                norm.into_bytes()
            }
        }
    }
}
