Partitions the given CSV data into chunks based on the value of a column

The files are written to the output directory with filenames based on the
values in the partition column and the `--filename` flag.

Usage:
    xsv partition [options] <column> <outdir> [<input>]
    xsv partition --help

partition options:
    --filename <filename>  A filename template to use when constructing
                           the names of the output files.  The string '{}'
                           will be replaced by a value based on the value
                           of the field, but sanitized for shell safety.
                           [default: {}.csv]
    -p, --prefix-length <n>  Truncate the partition column after the
                           specified number of bytes when creating the
                           output file.
    --drop                 Drop the partition column from results.

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. Otherwise, the first row will
                           appear in all chunks as the header row.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

struct Args {
    arg_column: SelectColumns,
    arg_input: Option<String>,
    arg_outdir: String,
    flag_filename: FilenameTemplate,
    flag_prefix_length: Option<usize>,
    flag_drop: bool,
    flag_no_headers: bool,
    flag_delimiter: Option<Delimiter>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = util::get_args(USAGE, argv)?;
    let args = Args {
        arg_column: SelectColumns::parse(a.get_str("<column>"))?,
        arg_input: a.get_opt_str("<input>"),
        arg_outdir: a.get_str("<outdir>").to_string(),
        flag_filename: FilenameTemplate::parse(a.get_str("--filename"))?,
        flag_prefix_length: a.get_opt_usize("--prefix-length")?,
        flag_drop: a.get_bool("--drop"),
        flag_no_headers: a.get_bool("--no-headers"),
        flag_delimiter: util::delimiter(&a)?,
    };
    fs::create_dir_all(&args.arg_outdir)?;

    let rconfig = args.rconfig();
    let mut rdr = rconfig.reader()?;
    let headers = rdr.byte_headers()?.clone();
    let key_col = args.key_column(&rconfig, &headers)?;
    let mut generator = WriterGenerator::new(args.flag_filename.clone());

    let mut writers: HashMap<Vec<u8>, Writer<Box<dyn io::Write>>> = HashMap::new();
    let mut row = ByteRecord::new();
    while rdr.read_byte_record(&mut row)? {
        // Decide what file to put this in.
        let column = row.get(key_col).unwrap();
        let key = match args.flag_prefix_length {
            // We truncate at a byte boundary.
            Some(len) if len < column.len() => &column[0..len],
            _ => column,
        };
        let entry = writers.entry(key.to_vec());
        let wtr = match entry {
            Entry::Occupied(occupied) => occupied.into_mut(),
            Entry::Vacant(vacant) => {
                // We have a new key, so make a new writer.
                let mut wtr = generator.writer(&args.arg_outdir, key)?;
                if !rconfig.no_headers {
                    if args.flag_drop {
                        wtr.write_record(
                            headers.iter().enumerate().filter(|&(i, _)| i != key_col).map(|(_, e)| e),
                        )?;
                    } else {
                        wtr.write_record(&headers)?;
                    }
                }
                vacant.insert(wtr)
            }
        };
        if args.flag_drop {
            wtr.write_record(row.iter().enumerate().filter(|&(i, _)| i != key_col).map(|(_, e)| e))?;
        } else {
            wtr.write_byte_record(&row)?;
        }
    }
    for (_, mut w) in writers.drain() {
        w.flush()?;
    }
    Ok(())
}

impl Args {
    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
            .select(self.arg_column.clone())
    }

    /// Get the column to use as a key.
    fn key_column(&self, rconfig: &Config, headers: &ByteRecord) -> CliResult<usize> {
        let select_cols = rconfig.selection(headers)?;
        if select_cols.len() == 1 {
