/// Generates unique filenames based on CSV values.
pub struct WriterGenerator {
    template: FilenameTemplate,
    used: HashSet<String>,
    non_unique: usize,
}

impl WriterGenerator {
    pub fn new(template: FilenameTemplate) -> WriterGenerator {
        WriterGenerator { template, used: HashSet::new(), non_unique: 0 }
    }

    /// Create a CSV writer for `key`. Does not add headers.
    pub fn writer<P>(&mut self, path: P, key: &[u8]) -> io::Result<Writer<Box<dyn io::Write>>>
    where
        P: AsRef<Path>,
    {
        let unique_value = self.unique_value(key);
        self.template.writer(path.as_ref(), &unique_value)
    }

    /// Generate a unique value for `key`, suitable for use in a filename.
    fn unique_value(&mut self, key: &[u8]) -> String {
        // Sanitize our key.
        let utf8_key = String::from_utf8_lossy(key).into_owned();
        let safe_key: String = utf8_key.chars().filter(|&c| is_word_char(c)).collect();
        let key = if safe_key.is_empty() { "empty".to_owned() } else { safe_key };

        // Now check for collisions.
        if !self.used.contains(&key) {
            self.used.insert(key.clone());
            key
        } else {
            loop {
                self.non_unique += 1;
                let candidate = format!("{}_{}", &key, self.non_unique);
                if !self.used.contains(&candidate) {
                    self.used.insert(candidate.clone());
                    return candidate;
                }
            }
        }
    }
}

/// Returns true for characters matched by the regex `\w` class.
fn is_word_char(c: char) -> bool {
    use std::sync::OnceLock;
    static RE: OnceLock<regex::Regex> = OnceLock::new();
    let re = RE.get_or_init(|| regex::Regex::new(r"^\w$").unwrap());
    let mut buf = [0u8; 4];
    re.is_match(c.encode_utf8(&mut buf))
}

/// A filename template of the form "{}.csv".
#[derive(Clone, Debug)]
pub struct FilenameTemplate {
    prefix: String,
    suffix: String,
}

impl FilenameTemplate {
    pub fn parse(template: &str) -> CliResult<FilenameTemplate> {
        let parts: Vec<&str> = template.split("{}").collect();
        if parts.len() == 2 {
            Ok(FilenameTemplate { prefix: parts[0].to_owned(), suffix: parts[1].to_owned() })
        } else {
            Err("The --filename argument must contain one '{}'.".into())
        }
    }

    /// Generate a new filename using `unique_value` to replace the `"{}"`
    /// in the template.
    pub fn filename(&self, unique_value: &str) -> String {
        format!("{}{}{}", &self.prefix, unique_value, &self.suffix)
    }

    /// Create a new file for writing.
    pub fn writer(&self, path: &Path, unique_value: &str) -> io::Result<Writer<Box<dyn io::Write>>> {
        let filename = self.filename(unique_value);
        let full_path = path.join(filename);
        if let Some(parent) = full_path.parent() {
            // We may be called concurrently, especially by parallel `xsv
            // split`, so be careful to avoid the `create_dir_all` race
            // condition.
            fs::create_dir_all(parent)?;
        }
        let spath = Some(full_path.display().to_string());
        Config::new(&spath).writer()
    }
}
