use std::fs;
use std::io;
use std::path::Path;
use std::thread;

use crate::cmd::partition::FilenameTemplate;
use crate::config::{Config, Delimiter};
use crate::csv::{ByteRecord, Writer};
use crate::index::Indexed;
use crate::util;
use crate::CliResult;

static USAGE: &str = "
Splits the given CSV data into chunks.

The files are written to the directory given with the name '{start}.csv',
where {start} is the index of the first record of the chunk (starting at 0).

Usage:
    xsv split [options] <outdir> [<input>]
    xsv split --help

split options:
    -s, --size <arg>       The number of records to write into each chunk.
                           [default: 500]
    -j, --jobs <arg>       The number of spliting jobs to run in parallel.
                           This only works when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]
    --filename <filename>  A filename template to use when constructing
                           the names of the output files.  The string '{}'
                           will be replaced by a value based on the value
                           of the field, but sanitized for shell safety.
                           [default: {}.csv]

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. Otherwise, the first row will
                           appear in all chunks as the header row.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Clone)]
struct Args {
    arg_input: Option<String>,
    arg_outdir: String,
    flag_size: usize,
    flag_jobs: usize,
    flag_filename: FilenameTemplate,
    flag_no_headers: bool,
    flag_delimiter: Option<Delimiter>,
}

pub fn run(argv: &[String]) -> CliResult<()> {
    let a = util::get_args(USAGE, argv)?;
    let args = Args {
        arg_input: a.get_opt_str("<input>"),
        arg_outdir: a.get_str("<outdir>").to_string(),
        flag_size: a.get_usize("--size")?,
        flag_jobs: a.get_usize("--jobs")?,
        flag_filename: FilenameTemplate::parse(a.get_str("--filename"))?,
        flag_no_headers: a.get_bool("--no-headers"),
        flag_delimiter: util::delimiter(&a)?,
    };
    if args.flag_size == 0 {
        return Err("--size must be greater than 0.".into());
    }
    fs::create_dir_all(&args.arg_outdir)?;

    match args.rconfig().indexed()? {
        Some(idx) => args.parallel_split(idx),
        None => args.sequential_split(),
    }
}

impl Args {
    fn sequential_split(&self) -> CliResult<()> {
        let rconfig = self.rconfig();
        let mut rdr = rconfig.reader()?;
        let headers = rdr.byte_headers()?.clone();

        let mut wtr: Option<Writer<Box<dyn io::Write>>> = None;
        let mut i = 0;
        let mut row = ByteRecord::new();
        while rdr.read_byte_record(&mut row)? {
            if wtr.is_none() || (i > 0 && i % self.flag_size == 0) {
                if let Some(mut w) = wtr.take() {
                    w.flush()?;
                }
                wtr = Some(self.new_writer(&headers, i)?);
            }
            wtr.as_mut().unwrap().write_byte_record(&row)?;
            i += 1;
        }
        if let Some(mut w) = wtr.take() {
            w.flush()?;
        }
        Ok(())
    }

    fn parallel_split(&self, idx: Indexed<fs::File, fs::File>) -> CliResult<()> {
        let nchunks = util::num_of_chunks(idx.count() as usize, self.flag_size);
        let njobs = util::njobs(self.flag_jobs);
        let mut handles = vec![];
        let mut results = vec![];
        for i in 0..nchunks {
            let args = self.clone();
            handles.push(thread::spawn(move || -> CliResult<()> {
                let conf = args.rconfig();
                let mut idx = conf.indexed()?.unwrap();
                let headers = idx.byte_headers()?.clone();

                let mut wtr = args.new_writer(&headers, i * args.flag_size)?;
                idx.seek((i * args.flag_size) as u64)?;
                for row in idx.byte_records().take(args.flag_size) {
                    let row = row?;
                    wtr.write_byte_record(&row)?;
                }
                wtr.flush()?;
                Ok(())
            }));
            if handles.len() >= njobs {
                for h in handles.drain(..) {
                    results.push(h.join().expect("thread panicked"));
                }
            }
        }
        for h in handles {
            results.push(h.join().expect("thread panicked"));
        }
        for r in results {
            r?;
        }
        Ok(())
    }

    fn new_writer(&self, headers: &ByteRecord, start: usize) -> CliResult<Writer<Box<dyn io::Write>>> {
        let dir = Path::new(&self.arg_outdir);
        let path = dir.join(self.flag_filename.filename(&format!("{}", start)));
        let spath = Some(path.display().to_string());
        let mut wtr = Config::new(&spath).writer()?;
        if !self.rconfig().no_headers {
            wtr.write_record(headers)?;
        }
        Ok(wtr)
    }

    fn rconfig(&self) -> Config {
        Config::new(&self.arg_input)
            .delimiter(self.flag_delimiter)
            .no_headers(self.flag_no_headers)
    }
}
