const WRITER_BUF_CAP: usize = 32 * 1024;

/// A CSV writer that buffers output and flushes on drop.
pub struct Writer<W: Write> {
    cfg: WriterBuilder,
    requires_quotes: [bool; 256],
    inner: Option<W>,
    buf: Vec<u8>,
    fields_written: u64,
    record_bytes: usize,
    first_field_count: Option<u64>,
    panicked: bool,
}

impl<W: Write> Drop for Writer<W> {
    fn drop(&mut self) {
        if self.inner.is_some() && !self.panicked {
            let _ = self.flush();
        }
    }
}

impl<W: Write> Writer<W> {
    fn needs_quotes(&self, field: &[u8]) -> bool {
        field.iter().any(|&b| self.requires_quotes[b as usize])
    }

    /// Writes bytes, splitting across buffer boundaries as needed.
    fn write_optimistic(&mut self, mut bytes: &[u8]) -> io::Result<()> {
        while !bytes.is_empty() {
            let remaining = WRITER_BUF_CAP - self.buf.len();
            if remaining == 0 {
                self.flush_buf()?;
                continue;
            }
            let n = std::cmp::min(remaining, bytes.len());
            self.buf.extend_from_slice(&bytes[..n]);
            bytes = &bytes[n..];
        }
        Ok(())
    }

    /// Writes bytes all at once; flushes first if they do not fit.
    fn write_pessimistic(&mut self, bytes: &[u8]) -> io::Result<()> {
        if WRITER_BUF_CAP - self.buf.len() < bytes.len() {
            self.flush_buf()?;
        }
        self.buf.extend_from_slice(bytes);
        Ok(())
    }

    pub fn write_field(&mut self, field: &[u8]) -> Result<()> {
        if self.fields_written > 0 {
            let d = self.cfg.delimiter;
            self.write_pessimistic(&[d])?;
            self.record_bytes += 1;
        }
        let quote = match self.cfg.quote_style {
            QuoteStyle::Always => true,
            QuoteStyle::Necessary => self.needs_quotes(field),
        };
        if quote {
            let q = self.cfg.quote;
            self.write_pessimistic(&[q])?;
            let mut rest = field;
            while !rest.is_empty() {
                match rest.iter().position(|&b| b == q) {
                    None => {
                        self.write_optimistic(rest)?;
                        rest = &rest[rest.len()..];
                    }
                    Some(i) => {
                        self.write_optimistic(&rest[..i])?;
                        if self.cfg.double_quote {
                            self.write_pessimistic(&[q, q])?;
                        } else {
                            let e = self.cfg.escape;
                            self.write_pessimistic(&[e, q])?;
                        }
                        rest = &rest[i + 1..];
                    }
                }
            }
            self.write_pessimistic(&[q])?;
            self.record_bytes += field.len() + 2;
        } else {
            self.write_optimistic(field)?;
            self.record_bytes += field.len();
        }
        self.fields_written += 1;
        Ok(())
    }

    fn check_field_count(&mut self) -> Result<()> {
        if !self.cfg.flexible {
            match self.first_field_count {
                None => self.first_field_count = Some(self.fields_written),
                Some(expected) if expected != self.fields_written => {
                    return Err(Error::UnequalLengths {
                        pos: None,
                        expected_len: expected,
                        len: self.fields_written,
                    });
                }
                Some(_) => {}
            }
        }
        Ok(())
    }

    pub fn write_terminator(&mut self) -> Result<()> {
        self.check_field_count()?;
        if self.record_bytes == 0 {
            let q = self.cfg.quote;
            self.write_pessimistic(&[q, q])?;
        }
        match self.cfg.terminator {
            Terminator::CRLF => self.write_pessimistic(b"\\r\\n")?,
            Terminator::Any(b) => self.write_pessimistic(&[b])?,
        }
        self.fields_written = 0;
        self.record_bytes = 0;
        Ok(())
    }

    pub fn write_record<I, T>(&mut self, record: I) -> Result<()>
    where
        I: IntoIterator<Item = T>,
        T: AsRef<[u8]>,
    {
        for f in record {
            self.write_field(f.as_ref())?;
        }
        self.write_terminator()
    }

    pub fn write_byte_record(&mut self, record: &ByteRecord) -> Result<()> {
        for f in record.iter() {
            self.write_field(f)?;
        }
        self.write_terminator()
    }

    /// Hands the buffered bytes to the underlying writer and flushes it.
    fn flush_buf(&mut self) -> io::Result<()> {
        if self.buf.is_empty() {
            return Ok(());
        }
        let w = self.inner.as_mut().unwrap();
        self.panicked = true;
        let res = w.write_all(&self.buf).and_then(|_| w.flush());
        self.panicked = false;
        self.buf.clear();
        res
    }

